        "rob.cpr_rated": ["en": "CPR-rated", "es": "homologado para RCP", "fr": "habilité RCP", "de": "für Reanimation zugelassen", "pt": "homologado para RCP", "it": "abilitato alla RCP", "ja": "心肺蘇生対応", "zh": "具备心肺复苏资质", "hi": "सीपीआर-सक्षम", "ar": "مؤهَّل للإنعاش"],
        "res.auto": ["en": "Auto-resuscitate", "es": "Reanimación automática", "fr": "Réanimation automatique", "de": "Automatisch wiederbeleben", "pt": "Reanimação automática", "it": "Rianimazione automatica", "ja": "自動で蘇生", "zh": "自动复苏", "hi": "स्वचालित पुनर्जीवन", "ar": "إنعاش تلقائي"],
        "res.signed.by": ["en": "Signed by {name} — CPR-rated robots may start compressions automatically and operate a fully-automatic AED. A shock still only follows the AED's own rhythm analysis.", "es": "Firmado por {name}: los robots homologados para RCP pueden iniciar las compresiones automáticamente y manejar un DEA totalmente automático. La descarga sigue dependiendo únicamente del análisis del ritmo que hace el propio DEA.", "fr": "Signé par {name} — les robots habilités RCP peuvent démarrer les compressions automatiquement et piloter un DAE entièrement automatique. Le choc ne suit toujours que la propre analyse du rythme par le DAE.", "de": "Unterschrieben von {name} — für Reanimation zugelassene Roboter dürfen die Kompressionen automatisch beginnen und einen vollautomatischen AED bedienen. Ein Schock folgt weiterhin nur der eigenen Rhythmusanalyse des AED.", "pt": "Assinado por {name} — os robôs homologados para RCP podem iniciar as compressões automaticamente e operar um DAE totalmente automático. O choque continua a seguir apenas a análise do ritmo feita pelo próprio DAE.", "it": "Firmato da {name} — i robot abilitati alla RCP possono avviare le compressioni automaticamente e usare un DAE completamente automatico. La scarica resta subordinata alla sola analisi del ritmo fatta dal DAE.", "ja": "{name} が署名しました — 心肺蘇生対応のロボットは、胸骨圧迫を自動で開始し、全自動 AED を扱えます。通電は、いまも AED 自身の心電図解析にのみ従います。", "zh": "由 {name} 签署 — 具备心肺复苏资质的机器人可自动开始按压并操作全自动 AED。放电仍然只依据 AED 自身的心律分析。", "hi": "{name} द्वारा हस्ताक्षरित — सीपीआर-सक्षम रोबोट अपने आप छाती दबाना शुरू कर सकते हैं और पूर्ण-स्वचालित AED चला सकते हैं। झटका फिर भी केवल AED के अपने लय-विश्लेषण के अनुसार ही दिया जाता है।", "ar": "وقّعه {name} — يجوز للآليّات المؤهَّلة للإنعاش أن تبدأ الضغطات تلقائيًا وأن تشغّل مزيل رجفان آليًا بالكامل. وتظل الصدمة تابعة لتحليل الجهاز نفسه لنظم القلب لا غير."],
        "fa": ["en": "First aid — step by step", "es": "Primeros auxilios, paso a paso", "fr": "Premiers secours — étape par étape", "de": "Erste Hilfe — Schritt für Schritt", "pt": "Primeiros socorros — passo a passo", "it": "Primo soccorso — passo dopo passo", "ja": "応急手当 — 手順ごとに", "zh": "急救 — 逐步进行", "hi": "प्राथमिक चिकित्सा — क़दम दर क़दम", "ar": "الإسعاف الأولي — خطوة بخطوة"],
        "fa.call": ["en": "📞 Call emergency services now", "es": "📞 Llama ya a los servicios de emergencia", "fr": "📞 Appelez les secours maintenant", "de": "📞 Rufe jetzt den Rettungsdienst", "pt": "📞 Ligue já para os serviços de emergência", "it": "📞 Chiama subito i soccorsi", "ja": "📞 いますぐ救急に連絡してください", "zh": "📞 立即拨打紧急服务电话", "hi": "📞 अभी आपातकालीन सेवाओं को कॉल करें", "ar": "📞 اتصل بخدمات الطوارئ الآن"],
        "fa.pace": ["en": "Pace: {cpm}/min · {ratio}", "es": "Ritmo: {cpm}/min · {ratio}", "fr": "Rythme : {cpm}/min · {ratio}", "de": "Takt: {cpm}/min · {ratio}", "pt": "Ritmo: {cpm}/min · {ratio}", "it": "Ritmo: {cpm}/min · {ratio}", "ja": "テンポ：{cpm}/分 · {ratio}", "zh": "节奏：{cpm}/分钟 · {ratio}", "hi": "गति: {cpm}/मिनट · {ratio}", "ar": "الإيقاع: {cpm}/دقيقة · {ratio}"],
        "fa.derived": ["en": "Derived from", "es": "Basado en", "fr": "Établi d'après", "de": "Abgeleitet aus", "pt": "Baseado em", "it": "Basato su", "ja": "根拠", "zh": "依据", "hi": "किस पर आधारित", "ar": "مستند إلى"],
        "fa.supports": ["en": "supports: {sources}", "es": "respalda: {sources}", "fr": "appuis : {sources}", "de": "gestützt auf: {sources}", "pt": "apoia-se em: {sources}", "it": "supporti: {sources}", "ja": "根拠：{sources}", "zh": "支持来源：{sources}", "hi": "समर्थन: {sources}", "ar": "المصادر: {sources}"],
        "fa.sealed": ["en": "🔒 Sealed in the PDI vault", "es": "🔒 Sellado en la bóveda PDI", "fr": "🔒 Scellé dans le coffre PDI", "de": "🔒 Im PDI-Tresor versiegelt", "pt": "🔒 Selado no cofre PDI", "it": "🔒 Sigillato nella cassaforte PDI", "ja": "🔒 PDI 保管庫に封印済み", "zh": "🔒 已封存于 PDI 保险库", "hi": "🔒 PDI वॉल्ट में सील", "ar": "🔒 مختوم في خزنة PDI"],
        "ns.pr": ["en": "When something breaks", "es": "Cuando algo falla", "fr": "Quand quelque chose casse", "de": "Wenn etwas kaputtgeht", "pt": "Quando algo falha", "it": "Quando qualcosa si rompe", "ja": "何かが壊れたとき", "zh": "出问题的时候", "hi": "जब कुछ टूटे", "ar": "حين يتعطّل شيء"],
        "ns.pr.explain": ["en": "This app can send a count of what failed — the operation and the HTTP status, the day it happened, and how many times. Not what you typed, not who you are, not which profile. Nothing that identifies you or anyone else.", "es": "Esta app puede enviar un recuento de lo que falló: la operación y el estado HTTP, el día en que ocurrió y cuántas veces. No lo que escribiste, no quién eres, no qué perfil. Nada que te identifique a ti ni a nadie.", "fr": "Cette application peut envoyer un décompte de ce qui a échoué : l'opération et le statut HTTP, le jour où c'est arrivé, et combien de fois. Pas ce que vous avez saisi, pas qui vous êtes, pas quel profil. Rien qui vous identifie, ni personne d'autre.", "de": "Diese App kann eine Zählung des Fehlgeschlagenen senden — den Vorgang und den HTTP-Status, den Tag und wie oft. Nicht, was du getippt hast, nicht, wer du bist, nicht, welches Profil. Nichts, was dich oder sonst jemanden identifiziert.", "pt": "Esta aplicação pode enviar uma contagem do que falhou: a operação e o estado HTTP, o dia em que aconteceu e quantas vezes. Não o que escreveu, não quem é, não qual perfil. Nada que o identifique a si nem a ninguém.", "it": "Questa app può inviare un conteggio di ciò che è fallito: l'operazione e lo stato HTTP, il giorno in cui è accaduto e quante volte. Non ciò che hai scritto, non chi sei, non quale profilo. Nulla che identifichi te o chiunque altro.", "ja": "このアプリは、失敗の件数を送ることができます — 操作と HTTP ステータス、起きた日、そして回数です。入力した内容も、あなたが誰かも、どのプロフィールかも送りません。あなたや他の誰かを特定するものは何も含みません。", "zh": "这个应用可以发送失败的计数 — 操作与 HTTP 状态、发生的日期、以及次数。不包括你输入的内容、你是谁、用的哪个资料。没有任何能指认你或别人的东西。", "hi": "यह ऐप विफलताओं की गिनती भेज सकता है — कौन-सा कार्य और HTTP स्थिति, किस दिन हुआ, और कितनी बार। आपने क्या लिखा, आप कौन हैं, कौन-सी प्रोफ़ाइल — ये नहीं। कुछ भी ऐसा नहीं जो आपकी या किसी की पहचान बताए।", "ar": "يمكن لهذا التطبيق أن يرسل عددًا لما أخفق — العملية وحالة HTTP، واليوم الذي وقع فيه، وكم مرة. لا ما كتبته، ولا من أنت، ولا أي ملف. لا شيء يعرّفك أو يعرّف أحدًا غيرك."],
        "ns.pr.nowhere": ["en": "This build reports nowhere. Failures are counted on this device and never leave it.", "es": "Esta compilación no informa a ninguna parte. Los fallos se cuentan en este dispositivo y nunca salen de él.", "fr": "Cette version ne signale rien nulle part. Les échecs sont comptés sur cet appareil et n'en sortent jamais.", "de": "Dieser Build meldet nirgendwohin. Fehler werden auf diesem Gerät gezählt und verlassen es nie.", "pt": "Esta compilação não reporta a lado nenhum. As falhas são contadas neste dispositivo e nunca saem dele.", "it": "Questa build non segnala da nessuna parte. Gli errori sono contati su questo dispositivo e non lo lasciano mai.", "ja": "このビルドはどこにも報告しません。失敗はこの端末で数えられ、端末の外に出ることはありません。", "zh": "这个版本不向任何地方上报。失败只在本机计数，永远不会离开这台设备。", "hi": "यह बिल्ड कहीं रिपोर्ट नहीं करता। विफलताएँ इसी डिवाइस पर गिनी जाती हैं और कभी बाहर नहीं जातीं।", "ar": "هذه النسخة لا ترسل تقارير إلى أي جهة. تُحصى الإخفاقات على هذا الجهاز ولا تغادره أبدًا."],
        "ns.pr.owed": ["en": "Nothing is owed. Either nothing has failed, or everything that has was already reported.", "es": "No hay nada pendiente. O no ha fallado nada, o todo lo que falló ya se informó.", "fr": "Rien n'est dû. Soit rien n'a échoué, soit tout ce qui a échoué a déjà été signalé.", "de": "Es steht nichts aus. Entweder ist nichts fehlgeschlagen, oder alles Fehlgeschlagene wurde bereits gemeldet.", "pt": "Não há nada em dívida. Ou nada falhou, ou tudo o que falhou já foi reportado.", "it": "Non c'è nulla in sospeso. O non è fallito nulla, o tutto ciò che è fallito è già stato segnalato.", "ja": "送るべきものはありません。何も失敗していないか、失敗したものはすべて報告済みです。", "zh": "没有待发送的内容。要么什么都没失败，要么失败过的都已上报。", "hi": "कुछ भी बकाया नहीं है। या तो कुछ विफल नहीं हुआ, या जो हुआ वह पहले ही भेजा जा चुका है।", "ar": "لا شيء معلّق. إما أن شيئًا لم يخفق، وإما أن كل ما أخفق قد أُبلغ عنه سلفًا."],
        "ns.pr.send": ["en": "Send counts", "es": "Enviar los recuentos", "fr": "Envoyer les décomptes", "de": "Zählungen senden", "pt": "Enviar as contagens", "it": "Invia i conteggi", "ja": "件数を送る", "zh": "发送计数", "hi": "गिनती भेजें", "ar": "أرسل الأعداد"],
        "ns.pr.dont": ["en": "Do not send", "es": "No enviar", "fr": "Ne pas envoyer", "de": "Nicht senden", "pt": "Não enviar", "it": "Non inviare", "ja": "送らない", "zh": "不要发送", "hi": "मत भेजें", "ar": "لا ترسل"],
        "ns.pr.toggle": ["en": "Send failure counts", "es": "Enviar recuentos de fallos", "fr": "Envoyer les décomptes d'échecs", "de": "Fehlerzählungen senden", "pt": "Enviar contagens de falhas", "it": "Invia i conteggi degli errori", "ja": "失敗の件数を送る", "zh": "发送失败计数", "hi": "विफलताओं की गिनती भेजें", "ar": "أرسل أعداد الإخفاقات"],
        "ns.pr.show": ["en": "Show what would be sent", "es": "Mostrar lo que se enviaría", "fr": "Montrer ce qui serait envoyé", "de": "Zeigen, was gesendet würde", "pt": "Mostrar o que seria enviado", "it": "Mostra ciò che verrebbe inviato", "ja": "送られる内容を表示", "zh": "查看将要发送的内容", "hi": "जो भेजा जाएगा वह दिखाएँ", "ar": "أظهر ما سيُرسل"],
        "ns.pr.hide": ["en": "Hide what would be sent", "es": "Ocultar lo que se enviaría", "fr": "Masquer ce qui serait envoyé", "de": "Verbergen, was gesendet würde", "pt": "Ocultar o que seria enviado", "it": "Nascondi ciò che verrebbe inviato", "ja": "送られる内容を隠す", "zh": "隐藏将要发送的内容", "hi": "जो भेजा जाएगा वह छिपाएँ", "ar": "أخفِ ما سيُرسل"],
        "fam": ["en": "Family watch", "es": "Vigilancia familiar", "fr": "Veille familiale", "de": "Familienwache", "pt": "Vigilância familiar", "it": "Sorveglianza familiare", "ja": "家族の見守り", "zh": "家庭守护", "hi": "परिवार की निगरानी", "ar": "رعاية العائلة"],
        "fam.mine": ["en": "My family", "es": "Mi familia", "fr": "Ma famille", "de": "Meine Familie", "pt": "A minha família", "it": "La mia famiglia", "ja": "わたしの家族", "zh": "我的家人", "hi": "मेरा परिवार", "ar": "عائلتي"],
        "fam.setup": ["en": "Set up my child", "es": "Configurar la cuenta de mi hijo o hija", "fr": "Configurer le compte de mon enfant", "de": "Konto meines Kindes einrichten", "pt": "Configurar a conta do meu filho ou filha", "it": "Configura l'account di mio figlio o figlia", "ja": "子どものアカウントを用意する", "zh": "为我的孩子设置", "hi": "अपने बच्चे का खाता बनाएँ", "ar": "أعِدّ حساب طفلي"],
        "fam.create": ["en": "Create child account", "es": "Crear la cuenta infantil", "fr": "Créer le compte enfant", "de": "Kinderkonto erstellen", "pt": "Criar a conta infantil", "it": "Crea l'account per il minore", "ja": "子どもアカウントを作成", "zh": "创建儿童账户", "hi": "बच्चे का खाता बनाएँ", "ar": "أنشئ حساب الطفل"],
        "fam.created": ["en": "Child account created", "es": "Cuenta infantil creada", "fr": "Compte enfant créé", "de": "Kinderkonto erstellt", "pt": "Conta infantil criada", "it": "Account per il minore creato", "ja": "子どもアカウントを作成しました", "zh": "儿童账户已创建", "hi": "बच्चे का खाता बन गया", "ar": "أُنشئ حساب الطفل"],
        "fam.enrol": ["en": "You enroll as the recorded parent/guardian. The account starts cautious, with you as the emergency contact; cloud sharing stays off. The auto-defib waiver can never be signed for a minor.", "es": "Te inscribes como madre, padre o tutor registrado. La cuenta empieza en modo cauteloso, contigo como contacto de emergencia, y el uso compartido en la nube queda desactivado. El consentimiento de desfibrilación automática nunca puede firmarse para un menor.", "fr": "Vous vous inscrivez comme parent ou tuteur enregistré. Le compte démarre en mode prudent, avec vous comme contact d'urgence ; le partage dans le nuage reste désactivé. La renonciation pour défibrillation automatique ne peut jamais être signée pour un mineur.", "de": "Du wirst als eingetragene sorgeberechtigte Person geführt. Das Konto startet vorsichtig, mit dir als Notfallkontakt; die Cloud-Freigabe bleibt aus. Die Verzichtserklärung für die automatische Defibrillation kann für Minderjährige niemals unterschrieben werden.", "pt": "Inscreve-se como mãe, pai ou tutor registado. A conta começa em modo cauteloso, consigo como contacto de emergência, e a partilha na nuvem fica desligada. O consentimento de desfibrilhação automática nunca pode ser assinado para um menor.", "it": "Ti registri come genitore o tutore. L'account parte in modalità cauta, con te come contatto di emergenza, e la condivisione nel cloud resta disattivata. La liberatoria per la defibrillazione automatica non può mai essere firmata per un minore.", "ja": "あなたは記録上の親権者として登録されます。アカウントは慎重な設定で始まり、緊急連絡先はあなたです。クラウド共有はオフのままです。自動除細動の同意書は、未成年について署名することは決してできません。", "zh": "你将作为登记在册的家长或监护人。账户以谨慎模式启动，紧急联系人是你，云端共享保持关闭。自动除颤授权书永远不能为未成年人签署。", "hi": "आप दर्ज अभिभावक के रूप में पंजीकृत होते हैं। खाता सतर्क मोड में शुरू होता है, आपात संपर्क आप हैं, और क्लाउड साझाकरण बंद रहता है। स्वतः-डिफ़िब का अनुमति-पत्र किसी नाबालिग़ के लिए कभी हस्ताक्षरित नहीं किया जा सकता।", "ar": "تُسجَّل بصفتك ولي الأمر المدوَّن. يبدأ الحساب على وضع حذر، وأنت جهة الاتصال في الطوارئ، وتبقى المشاركة السحابية معطّلة. ولا يمكن أبدًا توقيع تنازل إزالة الرجفان التلقائي عن قاصر."],
        "fam.token": ["en": "Device token — shown once, put it on their watch or phone:", "es": "Token del dispositivo: se muestra una sola vez; ponlo en su reloj o teléfono:", "fr": "Jeton d'appareil — affiché une seule fois, mettez-le sur sa montre ou son téléphone :", "de": "Gerätetoken — wird einmal angezeigt; trag ihn auf ihrer Uhr oder ihrem Telefon ein:", "pt": "Token do dispositivo — mostrado uma só vez; coloque-o no relógio ou telefone dele ou dela:", "it": "Token del dispositivo — mostrato una sola volta, mettilo sul suo orologio o telefono:", "ja": "端末トークン — 一度だけ表示されます。お子さんの時計か携帯に登録してください：", "zh": "设备令牌 — 只显示一次，请填入他们的手表或手机：", "hi": "डिवाइस टोकन — केवल एक बार दिखेगा, इसे उनकी घड़ी या फ़ोन पर डालिए:", "ar": "رمز الجهاز — يُعرض مرة واحدة، ضعه على ساعته أو هاتفه:"],
        "fam.keep": ["en": "Keep the link", "es": "Mantener el vínculo", "fr": "Conserver le lien", "de": "Verknüpfung behalten", "pt": "Manter a ligação", "it": "Mantieni il collegamento", "ja": "つながりを保つ", "zh": "保留关联", "hi": "कड़ी बनाए रखें", "ar": "أبقِ الارتباط"],
        "fam.unlink": ["en": "Unlink", "es": "Desvincular", "fr": "Dissocier", "de": "Trennen", "pt": "Desvincular", "it": "Scollega", "ja": "リンク解除", "zh": "取消关联", "hi": "अनलिंक करें", "ar": "إلغاء الربط"],
        "fam.unlink.this": ["en": "Unlink this child", "es": "Desvincular a este menor", "fr": "Dissocier cet enfant", "de": "Dieses Kind trennen", "pt": "Desvincular este menor", "it": "Scollega questo minore", "ja": "この子のつながりを解除", "zh": "解除与这个孩子的关联", "hi": "इस बच्चे को अलग करें", "ar": "افصل ارتباط هذا الطفل"],
        "fam.unlinked": ["en": "Oversight ended", "es": "La supervisión ha terminado", "fr": "La surveillance a pris fin", "de": "Die Aufsicht ist beendet", "pt": "A supervisão terminou", "it": "La supervisione è terminata", "ja": "見守りを終了しました", "zh": "监护已结束", "hi": "निगरानी समाप्त", "ar": "انتهت الرعاية"],
        "fam.theirs": ["en": "Their account, their guardian, and their own record are not deleted by unlinking — only your view of them ends.", "es": "Su cuenta, su guardián y su propio registro no se borran al desvincular: solo termina tu acceso a ellos.", "fr": "Son compte, son gardien et son propre dossier ne sont pas supprimés par la dissociation — seule votre vue sur eux prend fin.", "de": "Ihr Konto, ihr Guardian und ihre eigene Akte werden durch das Trennen nicht gelöscht — nur dein Blick darauf endet.", "pt": "A conta, o guardião e o registo próprio não são apagados ao desvincular — apenas termina a sua vista sobre eles.", "it": "Il suo account, il suo guardiano e il suo archivio non vengono cancellati dallo scollegamento — finisce solo la tua visuale su di loro.", "ja": "つながりを解除しても、その子のアカウント・ガーディアン・記録は消えません。終わるのは、あなたから見えることだけです。", "zh": "解除关联不会删除他们的账户、守护者或他们自己的记录 — 结束的只是你对这些的查看权限。", "hi": "अलग करने से उनका खाता, उनका गार्जियन और उनका अपना रिकॉर्ड नहीं मिटता — बस उन तक आपकी पहुँच समाप्त होती है।", "ar": "لا يحذف فصلُ الارتباط حسابَه ولا حارسَه ولا سجلَّه — إنما ينتهي اطّلاعك أنت فقط."],
        "fam.controls": ["en": "Device controls", "es": "Controles del dispositivo", "fr": "Contrôles de l'appareil", "de": "Gerätesteuerung", "pt": "Controlos do dispositivo", "it": "Controlli del dispositivo", "ja": "端末の設定", "zh": "设备控制", "hi": "डिवाइस नियंत्रण", "ar": "ضوابط الجهاز"],
        "fam.pause": ["en": "Pause guidance", "es": "Pausar las indicaciones", "fr": "Suspendre les conseils", "de": "Hinweise pausieren", "pt": "Pausar as orientações", "it": "Metti in pausa le indicazioni", "ja": "案内を一時停止", "zh": "暂停指导", "hi": "मार्गदर्शन रोकें", "ar": "أوقِف الإرشاد مؤقتًا"],
        "fam.pause.sub": ["en": "Pause and quiet hours hold everyday guidance only — monitoring, crisis escalation, and the emergency path never pause.", "es": "La pausa y las horas de silencio detienen solo las indicaciones cotidianas: la vigilancia, la escalada de crisis y la vía de emergencia nunca se pausan.", "fr": "La pause et les heures calmes ne suspendent que les conseils du quotidien — la surveillance, l'escalade de crise et la voie d'urgence ne s'arrêtent jamais.", "de": "Pause und Ruhezeiten halten nur die alltäglichen Hinweise an — Überwachung, Krisen-Eskalation und der Notfallweg pausieren nie.", "pt": "A pausa e as horas de silêncio suspendem apenas as orientações do dia a dia — a vigilância, a escalada de crise e a via de emergência nunca param.", "it": "La pausa e le ore di silenzio fermano solo le indicazioni quotidiane — il monitoraggio, l'escalation di crisi e la via d'emergenza non si fermano mai.", "ja": "一時停止と静かな時間が止めるのは、日々の案内だけです。見守り、危機の段階上昇、緊急の経路が止まることはありません。", "zh": "暂停与免打扰时段只会停下日常指导 — 监测、危机升级和紧急通路从不暂停。", "hi": "विराम और शांत घंटे केवल रोज़मर्रा के मार्गदर्शन को रोकते हैं — निगरानी, संकट-वृद्धि और आपातकालीन रास्ता कभी नहीं रुकते।", "ar": "الإيقاف المؤقت وساعات الهدوء تُوقف الإرشاد اليومي وحده — أما المراقبة وتصعيد الأزمات ومسار الطوارئ فلا تتوقف أبدًا."],
        "fam.apply": ["en": "Apply", "es": "Aplicar", "fr": "Appliquer", "de": "Anwenden", "pt": "Aplicar", "it": "Applica", "ja": "適用", "zh": "应用", "hi": "लागू करें", "ar": "طبّق"],
        "fam.quiet": ["en": "Nothing in the window — quiet is good news.", "es": "Nada en el periodo: el silencio es buena señal.", "fr": "Rien sur la période — le calme est une bonne nouvelle.", "de": "Nichts im Zeitraum — Ruhe ist eine gute Nachricht.", "pt": "Nada no período — o silêncio é boa notícia.", "it": "Niente nel periodo — il silenzio è una buona notizia.", "ja": "この期間には何もありません。静かなのは良い知らせです。", "zh": "这段时间没有任何记录 — 平静就是好消息。", "hi": "इस अवधि में कुछ नहीं — शांति अच्छी ख़बर है।", "ar": "لا شيء في هذه المدة — والهدوء خبر سار."],
        "fam.scope.full": ["en": "full (under 13)", "es": "completa (menores de 13)", "fr": "complète (moins de 13 ans)", "de": "vollständig (unter 13)", "pt": "completa (menores de 13)", "it": "completa (sotto i 13 anni)", "ja": "全面（13歳未満）", "zh": "完全（13 岁以下）", "hi": "पूर्ण (13 वर्ष से कम)", "ar": "كاملة (دون 13)"],
        "fam.scope.alerts": ["en": "alerts only (teen)", "es": "solo avisos (adolescente)", "fr": "alertes seulement (adolescent)", "de": "nur Warnungen (Jugendliche)", "pt": "só alertas (adolescente)", "it": "solo avvisi (adolescente)", "ja": "通知のみ（ティーン）", "zh": "仅提醒（青少年）", "hi": "केवल सूचनाएँ (किशोर)", "ar": "التنبيهات فقط (مراهق)"],
        "fam.oversight": ["en": "Oversight: {scope}", "es": "Supervisión: {scope}", "fr": "Surveillance : {scope}", "de": "Aufsicht: {scope}", "pt": "Supervisão: {scope}", "it": "Supervisione: {scope}", "ja": "見守り：{scope}", "zh": "监护：{scope}", "hi": "निगरानी: {scope}", "ar": "الرعاية: {scope}"],
        "fam.tapped": ["en": "⌚︎ TAPPED", "es": "⌚︎ TOCADO", "fr": "⌚︎ TOUCHÉ", "de": "⌚︎ GETIPPT", "pt": "⌚︎ TOCADO", "it": "⌚︎ TOCCATO", "ja": "⌚︎ タップされました", "zh": "⌚︎ 已轻点", "hi": "⌚︎ टैप किया गया", "ar": "⌚︎ نُقر"],
        "fam.critical": ["en": "⚠️ {n} critical event(s)", "es": "⚠️ {n} evento(s) crítico(s)", "fr": "⚠️ {n} événement(s) critique(s)", "de": "⚠️ {n} kritische(s) Ereignis(se)", "pt": "⚠️ {n} evento(s) crítico(s)", "it": "⚠️ {n} evento/i critico/i", "ja": "⚠️ 重大な事象 {n} 件", "zh": "⚠️ {n} 起危急事件", "hi": "⚠️ {n} गंभीर घटनाएँ", "ar": "⚠️ {n} حدثًا حرجًا"],
        "fam.st.paused": ["en": "paused", "es": "en pausa", "fr": "en pause", "de": "pausiert", "pt": "em pausa", "it": "in pausa", "ja": "一時停止中", "zh": "已暂停", "hi": "रुका हुआ", "ar": "موقوف مؤقتًا"],
        "fam.st.escalated": ["en": "escalated", "es": "escalado", "fr": "escaladé", "de": "eskaliert", "pt": "escalado", "it": "in escalation", "ja": "段階上昇", "zh": "已升级", "hi": "बढ़ाया गया", "ar": "مُصعَّد"],
        "fam.st.critical": ["en": "critical", "es": "crítico", "fr": "critique", "de": "kritisch", "pt": "crítico", "it": "critico", "ja": "重大", "zh": "危急", "hi": "गंभीर", "ar": "حرج"],
        "jcon.sources": ["en": "Data sources", "es": "Fuentes de datos", "fr": "Sources de données", "de": "Datenquellen", "pt": "Fontes de dados", "it": "Fonti di dati", "ja": "データの出どころ", "zh": "数据来源", "hi": "डेटा स्रोत", "ar": "مصادر البيانات"],
        "jcon.sources.sub": ["en": "JIM sees what you allow — flip a source off and it stops being read, immediately.", "es": "JIM ve lo que tú permites: desactiva una fuente y deja de leerse de inmediato.", "fr": "JIM voit ce que vous autorisez — désactivez une source et elle cesse aussitôt d'être lue.", "de": "JIM sieht, was du erlaubst — schalte eine Quelle aus, und sie wird sofort nicht mehr gelesen.", "pt": "O JIM vê o que você permite — desligue uma fonte e ela deixa de ser lida de imediato.", "it": "JIM vede ciò che permetti — disattiva una fonte e smette subito di essere letta.", "ja": "JIM が見るのは、あなたが許したものだけです。ある出どころを切れば、その時点で読まれなくなります。", "zh": "JIM 只看你允许的内容 — 关掉某个来源，它立刻不再被读取。", "hi": "JIM वही देखता है जिसकी आप अनुमति दें — किसी स्रोत को बंद कर दीजिए और उसे तुरंत पढ़ना बंद हो जाता है।", "ar": "لا يرى JIM إلا ما تسمح به — أطفئ مصدرًا فيتوقف عن القراءة منه فورًا."],
        "jcon.apps.sub": ["en": "Apple, Google, Microsoft, and Canva apps the Guardian can collect from and act through.", "es": "Aplicaciones de Apple, Google, Microsoft y Canva de las que el Guardián puede recopilar y a través de las que puede actuar.", "fr": "Applications Apple, Google, Microsoft et Canva depuis lesquelles le Gardien peut collecter et par lesquelles il peut agir.", "de": "Apps von Apple, Google, Microsoft und Canva, aus denen der Guardian sammeln und durch die er handeln kann.", "pt": "Aplicações da Apple, Google, Microsoft e Canva das quais o Guardião pode recolher e através das quais pode agir.", "it": "App di Apple, Google, Microsoft e Canva da cui il Guardiano può raccogliere e attraverso cui può agire.", "ja": "Apple、Google、Microsoft、Canva のアプリ。ガーディアンはそこから集め、そこを通して動けます。", "zh": "Apple、Google、Microsoft 和 Canva 的应用 — 守护者可以从中收集并经由它们行动。", "hi": "Apple, Google, Microsoft और Canva के ऐप, जिनसे गार्जियन सामग्री ले सकता है और जिनके ज़रिए काम कर सकता है।", "ar": "تطبيقات Apple وGoogle وMicrosoft وCanva التي يمكن للحارس الجمع منها والعمل عبرها."],
        "jcon.notdo": ["en": "What JIM does not do", "es": "Lo que JIM no hace", "fr": "Ce que JIM ne fait pas", "de": "Was JIM nicht tut", "pt": "O que o JIM não faz", "it": "Ciò che JIM non fa", "ja": "JIM がしないこと", "zh": "JIM 不做的事", "hi": "JIM क्या नहीं करता", "ar": "ما لا يفعله JIM"],
        "jcon.rooms": ["en": "Rooms", "es": "Salas", "fr": "Salles", "de": "Räume", "pt": "Salas", "it": "Stanze", "ja": "ルーム", "zh": "房间", "hi": "कक्ष", "ar": "الغرف"],
        "jcon.rooms.none": ["en": "No rooms open right now. A community shelf that cannot load is a quiet screen, not an error.", "es": "Ahora mismo no hay ninguna sala abierta. Un estante comunitario que no carga es una pantalla en silencio, no un error.", "fr": "Aucune salle ouverte pour l'instant. Une étagère communautaire qui ne charge pas est un écran silencieux, pas une erreur.", "de": "Gerade sind keine Räume offen. Ein Gemeinschaftsregal, das nicht lädt, ist ein stiller Bildschirm, kein Fehler.", "pt": "Nenhuma sala aberta neste momento. Uma prateleira comunitária que não carrega é um ecrã silencioso, não um erro.", "it": "Nessuna stanza aperta al momento. Uno scaffale comunitario che non si carica è una schermata silenziosa, non un errore.", "ja": "いま開いているルームはありません。コミュニティの棚が読み込めないのは、静かな画面であってエラーではありません。", "zh": "目前没有开放的房间。社区书架加载不出来，只是一块安静的屏幕，不是错误。", "hi": "अभी कोई कक्ष खुला नहीं है। समुदाय की शेल्फ़ का न खुलना एक शांत स्क्रीन है, त्रुटि नहीं।", "ar": "لا غرف مفتوحة الآن. ورفٌّ مجتمعي لا يُحمَّل شاشةٌ هادئة، لا خطأ."],
        "jcon.rooms.lang": ["en": "Rooms are listed as QRME serves them; you read {lang}.", "es": "Las salas se listan tal como QRME las sirve; tú lees en {lang}.", "fr": "Les salles sont listées telles que QRME les fournit ; vous lisez en {lang}.", "de": "Die Räume erscheinen so, wie QRME sie liefert; du liest {lang}.", "pt": "As salas são listadas tal como o QRME as serve; você lê em {lang}.", "it": "Le stanze sono elencate come le fornisce QRME; tu leggi in {lang}.", "ja": "ルームは QRME が返すままに並びます。あなたが読むのは {lang} です。", "zh": "房间按 QRME 提供的原样列出；你阅读的是 {lang}。", "hi": "कक्ष वैसे ही सूचीबद्ध हैं जैसे QRME उन्हें देता है; आप {lang} पढ़ते हैं।", "ar": "تُعرض الغرف كما يقدّمها QRME، وأنت تقرأ بـ {lang}."],
        "jcon.near": ["en": "Near you", "es": "Cerca de ti", "fr": "Près de vous", "de": "In deiner Nähe", "pt": "Perto de si", "it": "Vicino a te", "ja": "近くの場所", "zh": "你附近", "hi": "आपके पास", "ar": "قربك"],
        "jcon.places.none": ["en": "No places claimed yet.", "es": "Todavía no se ha reclamado ningún lugar.", "fr": "Aucun lieu revendiqué pour l'instant.", "de": "Noch keine Orte beansprucht.", "pt": "Ainda não há lugares reclamados.", "it": "Nessun luogo ancora rivendicato.", "ja": "まだ登録された場所はありません。", "zh": "还没有认领的地点。", "hi": "अभी तक कोई स्थान दर्ज नहीं।", "ar": "لا أماكن مُطالَب بها بعد."],
        "jcon.loading": ["en": "Loading the door…", "es": "Abriendo la puerta…", "fr": "Ouverture de la porte…", "de": "Die Tür wird geladen …", "pt": "A abrir a porta…", "it": "Sto aprendo la porta…", "ja": "入口を読み込んでいます…", "zh": "正在打开这道门…", "hi": "दरवाज़ा खुल रहा है…", "ar": "جارٍ فتح الباب…"],
