        "ns.ch.cam.for": ["en": "What it is for (optional)", "es": "Para qué es (opcional)", "fr": "À quoi ça sert (facultatif)", "de": "Wofür es ist (optional)", "pt": "Para que serve (opcional)", "it": "A cosa serve (facoltativo)", "ja": "何のためか（任意）", "zh": "用途（可选）", "hi": "किसलिए है (वैकल्पिक)", "ar": "لأي غرض (اختياري)"],
        "ns.ch.cam.site": ["en": "Choose a site first.", "es": "Elige primero una zona.", "fr": "Choisissez d'abord une zone.", "de": "Wählen Sie zuerst eine Stelle.", "pt": "Escolha primeiro uma zona.", "it": "Scegli prima una zona.", "ja": "まず部位を選んでください。", "zh": "请先选择部位。", "hi": "पहले स्थान चुनें।", "ar": "اختر الموضع أولاً."],
        "ns.ch.cam.note": ["en": "Note (optional)", "es": "Nota (opcional)", "fr": "Note (facultatif)", "de": "Notiz (optional)", "pt": "Nota (opcional)", "it": "Nota (facoltativa)", "ja": "メモ（任意）", "zh": "备注（可选）", "hi": "नोट (वैकल्पिक)", "ar": "ملاحظة (اختياري)"],
        "ns.ch.cam.consent": ["en": "This is an intimate site and I am choosing to record it.", "es": "Es una zona íntima y elijo registrarla.", "fr": "C'est une zone intime et je choisis de l'enregistrer.", "de": "Dies ist eine intime Stelle, und ich entscheide mich, sie aufzunehmen.", "pt": "É uma zona íntima e escolho registá-la.", "it": "È una zona intima e scelgo di registrarla.", "ja": "これはプライベートな部位であり、私は記録することを選びます。", "zh": "这是隐私部位，我选择记录它。", "hi": "यह निजी अंग है और मैं इसे दर्ज करना चुन रहा/रही हूँ।", "ar": "هذا موضع حسّاس وأنا أختار تسجيله."],
        "ns.ch.cam.intimate": ["en": "intimate", "es": "íntimo", "fr": "intime", "de": "intim", "pt": "íntimo", "it": "intimo", "ja": "プライベート", "zh": "隐私部位", "hi": "निजी", "ar": "حسّاس"],
        "ns.ch.cam.attach": ["en": "Attach {n}to a referral", "es": "Adjuntar {n}a una derivación", "fr": "Joindre {n}à une orientation", "de": "{n}an eine Überweisung anhängen", "pt": "Anexar {n}a um encaminhamento", "it": "Allega {n}a un referto", "ja": "{n}件を紹介状に添付", "zh": "将{n}附到转诊", "hi": "{n}रेफ़रल में जोड़ें", "ar": "إرفاق {n}بإحالة"],
        "ns.ch.cam.withdraw": ["en": "Withdraw", "es": "Retirar", "fr": "Retirer", "de": "Zurückziehen", "pt": "Retirar", "it": "Ritira", "ja": "取り下げる", "zh": "撤回", "hi": "वापस लें", "ar": "سحب"],
        "ns.ch.cam.where": ["en": "Where on the body…", "es": "En qué parte del cuerpo…", "fr": "Où sur le corps…", "de": "Wo am Körper…", "pt": "Onde no corpo…", "it": "Dove sul corpo…", "ja": "体のどこ…", "zh": "身体哪个部位…", "hi": "शरीर पर कहाँ…", "ar": "أين في الجسم…"],
        "ns.ch.cam.tick": ["en": "Tick the box before choosing a file.", "es": "Marca la casilla antes de elegir un archivo.", "fr": "Cochez la case avant de choisir un fichier.", "de": "Setzen Sie das Häkchen, bevor Sie eine Datei wählen.", "pt": "Marque a caixa antes de escolher um ficheiro.", "it": "Spunta la casella prima di scegliere un file.", "ja": "ファイルを選ぶ前にチェックを入れてください。", "zh": "选择文件前请先勾选。", "hi": "फ़ाइल चुनने से पहले बॉक्स चिह्नित करें।", "ar": "ضع علامة في المربع قبل اختيار ملف."],
        "ns.vc.say.ph": ["en": "Something to say aloud", "es": "Algo para decir en voz alta", "fr": "Quelque chose à dire à voix haute", "de": "Etwas zum laut Vorlesen", "pt": "Algo para dizer em voz alta", "it": "Qualcosa da dire ad alta voce", "ja": "声に出して言うこと", "zh": "要朗读的内容", "hi": "ज़ोर से कहने के लिए कुछ", "ar": "شيء ليُقال بصوت عالٍ"],
        "ns.vc.speak": ["en": "Say it", "es": "Dilo", "fr": "Dites-le", "de": "Sag es", "pt": "Diga-o", "it": "Dillo", "ja": "言う", "zh": "说出来", "hi": "कहो", "ar": "قلها"],
        "ns.vc.talk": ["en": "Talk to it", "es": "Háblale", "fr": "Parlez-lui", "de": "Sprich mit ihm", "pt": "Fale com ele", "it": "Parlagli", "ja": "話しかける", "zh": "对它说话", "hi": "इससे बात करें", "ar": "تحدث إليه"],
        "ns.vc.stop": ["en": "Stop — send it", "es": "Detener — enviarlo", "fr": "Arrêter — l'envoyer", "de": "Stopp — abschicken", "pt": "Parar — enviar", "it": "Ferma — invialo", "ja": "停止 — 送信する", "zh": "停止 — 发送", "hi": "रोकें — भेजें", "ar": "توقف — أرسلها"],
        "ns.vc.mic.refused": ["en": "The microphone was refused — allow it in system settings to talk to the Guardian.", "es": "El micrófono fue rechazado: permítelo en los ajustes del sistema para hablar con el Guardián.", "fr": "Le microphone a été refusé — autorisez-le dans les réglages du système pour parler au Gardien.", "de": "Das Mikrofon wurde verweigert — erlauben Sie es in den Systemeinstellungen, um mit dem Guardian zu sprechen.", "pt": "O microfone foi recusado — permita-o nas definições do sistema para falar com o Guardião.", "it": "Il microfono è stato rifiutato — consentilo nelle impostazioni di sistema per parlare con il Guardian.", "ja": "マイクが拒否されました — ガーディアンと話すにはシステム設定で許可してください。", "zh": "麦克风被拒绝 — 请在系统设置中允许，以便与守护者对话。", "hi": "माइक्रोफ़ोन अस्वीकार किया गया — गार्जियन से बात करने के लिए सिस्टम सेटिंग्स में अनुमति दें।", "ar": "رُفض الميكروفون — اسمح به في إعدادات النظام للتحدث إلى الحارس."],
        "ns.vc.device": ["en": "No speaking service is configured — the device's own voice read it instead.", "es": "No hay servicio de voz configurado: la propia voz del dispositivo lo leyó en su lugar.", "fr": "Aucun service vocal n'est configuré — la voix de l'appareil l'a lu à la place.", "de": "Kein Sprachdienst eingerichtet — die eigene Stimme des Geräts hat es stattdessen vorgelesen.", "pt": "Nenhum serviço de voz configurado — a própria voz do dispositivo o leu em vez disso.", "it": "Nessun servizio vocale configurato — l'ha letto la voce del dispositivo.", "ja": "音声サービスが設定されていません — 代わりにデバイス自身の声が読み上げました。", "zh": "未配置语音服务 — 改由设备自己的声音朗读。", "hi": "कोई वाक् सेवा कॉन्फ़िगर नहीं है — इसके बजाय डिवाइस की अपनी आवाज़ ने इसे पढ़ा।", "ar": "لا توجد خدمة نطق مهيأة — قرأه صوت الجهاز نفسه بدلاً من ذلك."],
        "rch.ask": ["en": "Send it to go and ask", "es": "Envíalo a preguntar", "fr": "L'envoyer demander", "de": "Losschicken zum Fragen", "pt": "Envie-o a perguntar", "it": "Mandalo a chiedere", "ja": "尋ねに行かせる", "zh": "派它去问", "hi": "पूछने भेजें", "ar": "أرسله ليسأل"],
        "rch.ask.topic.ph": ["en": "Topic", "es": "Tema", "fr": "Sujet", "de": "Thema", "pt": "Tema", "it": "Argomento", "ja": "トピック", "zh": "主题", "hi": "विषय", "ar": "الموضوع"],
        "rch.ask.q.ph": ["en": "What do you want to know?", "es": "¿Qué quieres saber?", "fr": "Que voulez-vous savoir ?", "de": "Was wollen Sie wissen?", "pt": "O que quer saber?", "it": "Cosa vuoi sapere?", "ja": "何を知りたいですか？", "zh": "你想知道什么？", "hi": "आप क्या जानना चाहते हैं?", "ar": "ماذا تريد أن تعرف؟"],
        "rch.ask.go": ["en": "Go", "es": "Ir", "fr": "Aller", "de": "Los", "pt": "Ir", "it": "Vai", "ja": "行く", "zh": "出发", "hi": "जाओ", "ar": "انطلق"],
        "rch.ask.read": ["en": "Read", "es": "Leer", "fr": "Lire", "de": "Lesen", "pt": "Ler", "it": "Leggi", "ja": "読む", "zh": "阅读", "hi": "पढ़ें", "ar": "اقرأ"],
        "rch.ask.keep": ["en": "Keep what it learned", "es": "Conservar lo aprendido", "fr": "Garder ce qu'il a appris", "de": "Behalten, was er lernte", "pt": "Guardar o que aprendeu", "it": "Tieni ciò che ha imparato", "ja": "学んだことを保持", "zh": "保留它学到的", "hi": "जो सीखा उसे रखें", "ar": "احتفظ بما تعلّمه"],
        "rch.ask.price": ["en": "Redactions is how much of you was taken out before the question left, and left this host is whether it left at all. A screen that showed the findings and hid those two would be showing the answer and hiding what it cost.", "es": "«Redactions» es cuánto de ti se quitó antes de que la pregunta saliera, y «left this host» es si salió siquiera. Una pantalla que mostrara los hallazgos y ocultara esos dos estaría mostrando la respuesta y escondiendo lo que costó.", "fr": "« Redactions » dit combien de vous a été retiré avant que la question parte, et « left this host » dit si elle est partie tout court. Un écran qui montrerait les résultats en cachant ces deux-là montrerait la réponse en cachant son prix.", "de": "»Redactions« sagt, wie viel von Ihnen entfernt wurde, bevor die Frage aufbrach, und »left this host«, ob sie überhaupt aufbrach. Ein Bildschirm, der die Befunde zeigte und diese beiden versteckte, zeigte die Antwort und verbärge ihren Preis.", "pt": "«Redactions» é quanto de si foi retirado antes de a pergunta sair, e «left this host» é se sequer saiu. Um ecrã que mostrasse os resultados e escondesse esses dois estaria a mostrar a resposta e a esconder o que custou.", "it": "«Redactions» è quanto di te è stato tolto prima che la domanda partisse, e «left this host» è se è partita affatto. Uno schermo che mostrasse i risultati nascondendo quei due mostrerebbe la risposta nascondendo quanto è costata.", "ja": "「Redactions」は質問が出発する前にあなたのどれだけが取り除かれたかを、「left this host」はそもそも出発したかどうかを示します。所見を見せてこの二つを隠す画面は、答えを見せて代償を隠すことになります。", "zh": "「Redactions」是问题出发前从你身上删去了多少，「left this host」是它究竟有没有离开。若屏幕只展示发现而隐藏这两项，就是展示答案而隐藏代价。", "hi": "«Redactions» यह है कि प्रश्न निकलने से पहले आपका कितना हिस्सा हटाया गया, और «left this host» यह कि वह निकला भी या नहीं। जो स्क्रीन निष्कर्ष दिखाकर ये दोनों छिपाए, वह उत्तर दिखाकर उसकी कीमत छिपा रही होगी।", "ar": "«Redactions» تعني كم أُخذ منك قبل أن يغادر السؤال، و«left this host» تعني هل غادر أصلًا. الشاشة التي تعرض النتائج وتخفي هذين تعرض الجواب وتخفي ثمنه."],
        "rch.wrist.visits": ["en": "{n} community visits recorded — JIM points at QRME's rooms, QRME hosts them.", "es": "{n} visitas comunitarias registradas — JIM apunta a las salas de QRME, QRME las aloja.", "fr": "{n} visites communautaires enregistrées — JIM pointe vers les salles de QRME, QRME les héberge.", "de": "{n} Community-Besuche verzeichnet — JIM zeigt auf QRMEs Räume, QRME beherbergt sie.", "pt": "{n} visitas comunitárias registadas — o JIM aponta para as salas do QRME, o QRME aloja-as.", "it": "{n} visite alla community registrate — JIM punta alle stanze di QRME, QRME le ospita.", "ja": "コミュニティ訪問{n}件を記録 — JIMはQRMEのルームを指し示し、QRMEがホストします。", "zh": "已记录{n}次社区访问 — JIM指向QRME的房间，由QRME托管。", "hi": "{n} सामुदायिक भेंट दर्ज — JIM QRME के कमरों की ओर इशारा करता है, QRME उन्हें होस्ट करता है।", "ar": "سُجلت {n} زيارة مجتمعية — يشير JIM إلى غرف QRME، وQRME يستضيفها."],
        "feed.title": ["en": "Feed", "es": "Muro", "fr": "Fil", "de": "Feed", "pt": "Fluxo", "it": "Flusso", "ja": "フィード", "zh": "动态", "hi": "फ़ीड", "ar": "التدفّق"],
        "feed.cannotpost": ["en": "You cannot post from JIM. Publishing happens in QRME, under your own QRME identity.", "es": "No puedes publicar desde JIM. Publicar ocurre en QRME, con tu propia identidad de QRME.", "fr": "Vous ne pouvez pas publier depuis JIM. La publication se fait dans QRME, sous votre propre identité QRME.", "de": "Aus JIM heraus kann nichts veröffentlicht werden. Das Veröffentlichen geschieht in QRME, unter Ihrer eigenen QRME-Identität.", "pt": "Não podes publicar a partir do JIM. Publicar acontece no QRME, com a tua própria identidade QRME.", "it": "Da JIM non si pubblica. La pubblicazione avviene in QRME, con la tua identità QRME.", "ja": "JIM からは投稿できません。投稿は QRME で、あなた自身の QRME の身元で行います。", "zh": "不能从 JIM 发布。发布发生在 QRME，用你自己的 QRME 身份。", "hi": "आप JIM से पोस्ट नहीं कर सकते। प्रकाशन QRME में होता है, आपकी अपनी QRME पहचान से।", "ar": "لا يمكنك النشر من JIM. النشر يجري في QRME، بهويتك الخاصة هناك."],
        "feed.openinqrme": ["en": "Open it in QRME", "es": "Abrirlo en QRME", "fr": "L'ouvrir dans QRME", "de": "In QRME öffnen", "pt": "Abrir no QRME", "it": "Aprirlo in QRME", "ja": "QRME で開く", "zh": "在 QRME 中打开", "hi": "QRME में खोलें", "ar": "افتحه في QRME"],
        "feed.empty": ["en": "Nothing public right now.", "es": "Nada público ahora mismo.", "fr": "Rien de public pour l'instant.", "de": "Gerade nichts Öffentliches.", "pt": "Nada público neste momento.", "it": "Nulla di pubblico al momento.", "ja": "いま公開されているものはありません。", "zh": "此刻没有公开内容。", "hi": "अभी कुछ भी सार्वजनिक नहीं।", "ar": "لا شيء علني الآن."],
        "sfy.beacons": ["en": "Beacons", "es": "Balizas", "fr": "Balises", "de": "Baken", "pt": "Balizas", "it": "Beacon", "ja": "ビーコン", "zh": "信标", "hi": "बीकन", "ar": "المنارات"],
        "sfy.beacons.pitch": ["en": "A sticker someone can scan to reach help on your behalf. The scanner needs no account and sees only what you chose to put on the card.", "es": "Una pegatina que alguien puede escanear para pedir ayuda en tu nombre. Quien escanea no necesita cuenta y solo ve lo que decidiste poner en la tarjeta.", "fr": "Un autocollant que quelqu'un peut scanner pour appeler de l'aide en votre nom. Le scanneur n'a besoin d'aucun compte et ne voit que ce que vous avez choisi de mettre sur la carte.", "de": "Ein Aufkleber, den jemand scannen kann, um in Ihrem Namen Hilfe zu holen. Wer scannt, braucht kein Konto und sieht nur, was Sie auf die Karte setzen wollten.", "pt": "Um autocolante que alguém pode digitalizar para pedir ajuda em seu nome. Quem digitaliza não precisa de conta e vê apenas o que escolheu pôr no cartão.", "it": "Un adesivo che qualcuno può scansionare per chiedere aiuto per te. Chi scansiona non ha bisogno di account e vede solo ciò che hai scelto di mettere sulla scheda.", "ja": "誰かがスキャンして、あなたに代わって助けを呼べるステッカーです。スキャンする人にアカウントは要らず、見えるのはあなたがカードに載せると決めたものだけです。", "zh": "一张贴纸，别人扫一下就能代你求助。扫描者无需账户，只能看到你选择放上卡片的内容。", "hi": "एक स्टिकर जिसे कोई स्कैन करके आपकी ओर से मदद बुला सके। स्कैन करने वाले को खाता नहीं चाहिए और उसे केवल वही दिखता है जो आपने कार्ड पर रखना चुना।", "ar": "ملصق يمكن لأحد مسحه ليطلب النجدة نيابة عنك. الماسح لا يحتاج حسابًا ولا يرى إلا ما اخترت وضعه على البطاقة."],
        "sfy.beacons.label.ph": ["en": "Label (Front door)", "es": "Etiqueta (Puerta principal)", "fr": "Étiquette (Porte d'entrée)", "de": "Beschriftung (Haustür)", "pt": "Etiqueta (Porta da frente)", "it": "Etichetta (Porta d'ingresso)", "ja": "ラベル（玄関）", "zh": "标签（前门）", "hi": "लेबल (मुख्य द्वार)", "ar": "التسمية (الباب الأمامي)"],
        "sfy.beacons.where.ph": ["en": "Where it is (optional)", "es": "Dónde está (opcional)", "fr": "Où elle est (facultatif)", "de": "Wo sie ist (optional)", "pt": "Onde está (opcional)", "it": "Dov'è (facoltativo)", "ja": "設置場所（任意）", "zh": "它在哪里（可选）", "hi": "यह कहाँ है (वैकल्पिक)", "ar": "أين هي (اختياري)"],
        "sfy.beacons.place": ["en": "Place a beacon", "es": "Colocar una baliza", "fr": "Poser une balise", "de": "Eine Bake platzieren", "pt": "Colocar uma baliza", "it": "Colloca un beacon", "ja": "ビーコンを設置", "zh": "放置信标", "hi": "बीकन रखें", "ar": "ضع منارة"],
        "sfy.beacons.scans": ["en": "{n} scans", "es": "{n} escaneos", "fr": "{n} scans", "de": "{n} Scans", "pt": "{n} digitalizações", "it": "{n} scansioni", "ja": "スキャン{n}件", "zh": "{n}次扫描", "hi": "{n} स्कैन", "ar": "{n} مسحة"],
        "sfy.beacons.retired": ["en": "retired", "es": "retirada", "fr": "retirée", "de": "zurückgezogen", "pt": "retirada", "it": "ritirato", "ja": "引退済み", "zh": "已退役", "hi": "सेवानिवृत्त", "ar": "متقاعد"],
