        "aim.budget.cat.ph": ["en": "groceries", "es": "comida", "fr": "courses", "de": "Lebensmittel", "pt": "mercearia", "it": "spesa", "ja": "食料品", "zh": "杂货", "hi": "किराना", "ar": "بقالة"],
        "aim.budget.line": ["en": "{spent} of {limit} · {standing}", "es": "{spent} de {limit} · {standing}", "fr": "{spent} sur {limit} · {standing}", "de": "{spent} von {limit} · {standing}", "pt": "{spent} de {limit} · {standing}", "it": "{spent} su {limit} · {standing}", "ja": "{limit}中{spent} · {standing}", "zh": "{limit}中已用{spent} · {standing}", "hi": "{limit} में से {spent} · {standing}", "ar": "{spent} من {limit} · {standing}"],
        "aim.budget.none": ["en": "No limits set. Financial stress is one of the eight conditions JIM will take on, and a budget is how it learns the shape of yours.", "es": "Sin límites. El estrés financiero es una de las ocho condiciones que JIM atiende, y un presupuesto es como aprende la forma del tuyo.", "fr": "Aucune limite. Le stress financier est l'une des huit situations dont JIM se charge, et un budget est la façon dont il apprend la forme du vôtre.", "de": "Keine Grenzen gesetzt. Finanzieller Stress ist einer der acht Zustände, die JIM übernimmt, und ein Budget ist, wie es die Gestalt Ihres eigenen lernt.", "pt": "Sem limites definidos. O stress financeiro é uma das oito condições que o JIM assume, e um orçamento é como aprende a forma do seu.", "it": "Nessun limite impostato. Lo stress finanziario è una delle otto condizioni di cui JIM si occupa, e un budget è il modo in cui impara la forma del tuo.", "ja": "上限は未設定です。経済的ストレスはJIMが引き受ける八つの状態のひとつで、予算はあなたのそれの形を学ぶ手がかりです。", "zh": "尚未设定上限。财务压力是 JIM 会承接的八种状况之一，而预算正是它了解你这方面轮廓的途径。", "hi": "कोई सीमा तय नहीं। आर्थिक तनाव उन आठ स्थितियों में से एक है जिन्हें JIM संभालता है, और बजट ही वह तरीक़ा है जिससे वह आपकी स्थिति का आकार समझता है।", "ar": "لا حدود محددة. الضغط المالي أحد الحالات الثماني التي يتولاها JIM، والميزانية هي كيف يتعلم شكل حالتك."],
        "aim.budget.remove": ["en": "Remove", "es": "Quitar", "fr": "Retirer", "de": "Entfernen", "pt": "Remover", "it": "Rimuovi", "ja": "削除", "zh": "移除", "hi": "हटाएँ", "ar": "أزل"],
