        "hld.plan.canread": ["en": "Can read it: {list}", "es": "Pueden leerlo: {list}", "fr": "Peuvent le lire : {list}", "de": "Dürfen es lesen: {list}", "pt": "Podem lê-lo: {list}", "it": "Possono leggerlo: {list}", "ja": "読める者: {list}", "zh": "可读取者: {list}", "hi": "इसे पढ़ सकते हैं: {list}", "ar": "يمكنهم قراءته: {list}"],
        "hld.log": ["en": "Who has read your record", "es": "Quién ha leído tu registro", "fr": "Qui a lu votre dossier", "de": "Wer Ihre Akte gelesen hat", "pt": "Quem leu o seu registo", "it": "Chi ha letto il tuo registro", "ja": "あなたの記録を読んだ人", "zh": "谁读过你的记录", "hi": "आपका रिकॉर्ड किसने पढ़ा", "ar": "من قرأ سجلك"],
        "hld.log.empty": ["en": "The list below is empty because nothing is being recorded — not because nobody has looked. Those are different facts and this screen will not let them look the same.", "es": "La lista de abajo está vacía porque no se está registrando nada — no porque nadie haya mirado. Son hechos distintos y esta pantalla no dejará que parezcan iguales.", "fr": "La liste ci-dessous est vide parce que rien n'est enregistré — pas parce que personne n'a regardé. Ce sont deux faits différents et cet écran ne les laissera pas se ressembler.", "de": "Die Liste unten ist leer, weil nichts aufgezeichnet wird — nicht, weil niemand hineingesehen hat. Das sind verschiedene Tatsachen, und dieser Bildschirm lässt sie nicht gleich aussehen.", "pt": "A lista abaixo está vazia porque nada está a ser registado — não porque ninguém tenha olhado. São factos diferentes e este ecrã não os deixará parecer iguais.", "it": "L'elenco qui sotto è vuoto perché non si sta registrando nulla — non perché nessuno abbia guardato. Sono fatti diversi e questa schermata non li lascerà sembrare uguali.", "ja": "下のリストが空なのは、誰も見ていないからではなく、何も記録されていないからです。この二つは別の事実であり、この画面は両者を同じに見せません。", "zh": "下面的列表为空，是因为什么都没被记录 — 而不是因为无人查看过。这是两个不同的事实，本屏幕不会让它们看起来一样。", "hi": "नीचे की सूची इसलिए खाली है क्योंकि कुछ दर्ज ही नहीं हो रहा — इसलिए नहीं कि किसी ने देखा नहीं। ये दो अलग तथ्य हैं और यह स्क्रीन इन्हें एक जैसा नहीं दिखने देगी।", "ar": "القائمة أدناه فارغة لأن شيئًا لا يُسجَّل — لا لأن أحدًا لم يطّلع. هاتان حقيقتان مختلفتان، وهذه الشاشة لن تدعهما تبدوان متشابهتين."],
        "hld.log.kept": ["en": "An access record is being kept:", "es": "Se está llevando un registro de accesos:", "fr": "Un registre des accès est tenu :", "de": "Ein Zugriffsprotokoll wird geführt:", "pt": "Está a ser mantido um registo de acessos:", "it": "Si tiene un registro degli accessi:", "ja": "アクセス記録の保持:", "zh": "正在保留访问记录:", "hi": "पहुँच रिकॉर्ड रखा जा रहा है:", "ar": "يُحتفظ بسجل وصول:"],
        "hld.log.vaulted": ["en": "Sealed in a vault:", "es": "Sellado en una bóveda:", "fr": "Scellé dans un coffre :", "de": "In einem Tresor versiegelt:", "pt": "Selado num cofre:", "it": "Sigillato in un caveau:", "ja": "保管庫に封印:", "zh": "已封入保险库:", "hi": "तिजोरी में सील:", "ar": "مختوم في خزنة:"],
        "hld.where": ["en": "Where the answers come from", "es": "De dónde vienen las respuestas", "fr": "D'où viennent les réponses", "de": "Woher die Antworten kommen", "pt": "De onde vêm as respostas", "it": "Da dove vengono le risposte", "ja": "答えはどこから来るか", "zh": "答案从哪来", "hi": "उत्तर कहाँ से आते हैं", "ar": "من أين تأتي الإجابات"],
        "hld.where.cloud": ["en": "Cloud model: {model} · falls back to {fallback}", "es": "Modelo en la nube: {model} · recurre a {fallback}", "fr": "Modèle cloud : {model} · se rabat sur {fallback}", "de": "Cloud-Modell: {model} · fällt zurück auf {fallback}", "pt": "Modelo na nuvem: {model} · recorre a {fallback}", "it": "Modello cloud: {model} · ripiega su {fallback}", "ja": "クラウドモデル: {model} · 代替は{fallback}", "zh": "云端模型: {model} · 回退到{fallback}", "hi": "क्लाउड मॉडल: {model} · विकल्प {fallback}", "ar": "نموذج سحابي: {model} · يعود إلى {fallback}"],
        "set.cloud": ["en": "What you contribute", "es": "Lo que aportas", "fr": "Ce que vous contribuez", "de": "Was Sie beitragen", "pt": "O que contribui", "it": "Cosa contribuisci", "ja": "あなたが提供するもの", "zh": "你贡献了什么", "hi": "आप क्या योगदान देते हैं", "ar": "ما تساهم به"],
        "set.cloud.stop": ["en": "Stop contributing", "es": "Dejar de aportar", "fr": "Cesser de contribuer", "de": "Beitragen beenden", "pt": "Deixar de contribuir", "it": "Smetti di contribuire", "ja": "提供をやめる", "zh": "停止贡献", "hi": "योगदान बंद करें", "ar": "أوقف المساهمة"],
        "set.loc": ["en": "Where to look", "es": "Dónde buscar", "fr": "Où chercher", "de": "Wo gesucht wird", "pt": "Onde procurar", "it": "Dove cercare", "ja": "どこを探すか", "zh": "在哪里查找", "hi": "कहाँ देखना है", "ar": "أين يُبحث"],
        "set.loc.ph": ["en": "Town or city", "es": "Pueblo o ciudad", "fr": "Ville ou commune", "de": "Ort oder Stadt", "pt": "Vila ou cidade", "it": "Paese o città", "ja": "市区町村", "zh": "城镇或城市", "hi": "क़स्बा या शहर", "ar": "بلدة أو مدينة"],
        "set.loc.pitch": ["en": "Used only to find local rooms and events through the community door. Leave it empty and nothing local is searched for.", "es": "Se usa solo para encontrar salas y eventos locales a través de la puerta comunitaria. Déjalo vacío y no se buscará nada local.", "fr": "Utilisé uniquement pour trouver des salles et événements locaux via la porte communautaire. Laissez vide et rien de local n'est cherché.", "de": "Wird nur genutzt, um lokale Räume und Veranstaltungen über die Community-Tür zu finden. Leer lassen, und es wird nichts Lokales gesucht.", "pt": "Usado apenas para encontrar salas e eventos locais através da porta comunitária. Deixe vazio e nada local é procurado.", "it": "Usato solo per trovare stanze ed eventi locali tramite la porta della community. Lascialo vuoto e non si cerca nulla di locale.", "ja": "コミュニティの入口を通じて地元のルームやイベントを探すためだけに使われます。空欄にすれば地元の検索は一切行われません。", "zh": "仅用于通过社区入口查找本地房间和活动。留空则不搜索任何本地内容。", "hi": "केवल सामुदायिक द्वार से स्थानीय कमरे और आयोजन खोजने के लिए उपयोग होता है। खाली छोड़ें तो कुछ भी स्थानीय नहीं खोजा जाएगा।", "ar": "يُستخدم فقط للعثور على الغرف والفعاليات المحلية عبر باب المجتمع. اتركه فارغًا فلا يُبحث عن شيء محلي."],
        "sfy.pages": ["en": "What went out", "es": "Lo que salió", "fr": "Ce qui est parti", "de": "Was hinausging", "pt": "O que saiu", "it": "Cosa è uscito", "ja": "送信されたもの", "zh": "发出去的内容", "hi": "क्या भेजा गया", "ar": "ما الذي خرج"],
        "sfy.pages.pitch": ["en": "Every page JIM sent on your behalf, and whether it arrived. Shown because a message that failed to deliver is the one you most need to know about.", "es": "Cada aviso que JIM envió en tu nombre, y si llegó. Se muestra porque un mensaje que no se entregó es justo el que más necesitas conocer.", "fr": "Chaque appel que JIM a envoyé en votre nom, et s'il est arrivé. Affiché parce qu'un message non délivré est celui qu'il faut le plus connaître.", "de": "Jede Benachrichtigung, die JIM in Ihrem Namen sandte, und ob sie ankam. Gezeigt, weil eine nicht zugestellte Nachricht genau die ist, von der Sie wissen müssen.", "pt": "Cada aviso que o JIM enviou em seu nome, e se chegou. Mostrado porque uma mensagem que falhou a entrega é a que mais precisa de conhecer.", "it": "Ogni avviso che JIM ha inviato per te, e se è arrivato. Mostrato perché un messaggio non consegnato è proprio quello che più ti serve sapere.", "ja": "JIMがあなたに代わって送ったすべての呼び出しと、それが届いたかどうか。届かなかったメッセージこそ、最も知る必要があるものだからです。", "zh": "JIM 代你发出的每一次呼叫，以及它是否送达。之所以展示，是因为没能送达的那条消息，正是你最需要知道的。", "hi": "JIM ने आपकी ओर से भेजा हर संदेश, और वह पहुँचा या नहीं। इसलिए दिखाया गया क्योंकि जो संदेश पहुँच न सका, उसी के बारे में जानना सबसे ज़रूरी है।", "ar": "كل نداء أرسله JIM نيابة عنك، وهل وصل. يُعرض لأن الرسالة التي أخفقت في الوصول هي أكثر ما تحتاج معرفته."],
        "sfy.pages.none": ["en": "No pages sent.", "es": "No se enviaron avisos.", "fr": "Aucun appel envoyé.", "de": "Keine Benachrichtigungen gesendet.", "pt": "Nenhum aviso enviado.", "it": "Nessun avviso inviato.", "ja": "送信された呼び出しはありません。", "zh": "未发出任何呼叫。", "hi": "कोई संदेश नहीं भेजा गया।", "ar": "لم تُرسل أي نداءات."],
        "sfy.history": ["en": "History", "es": "Historial", "fr": "Historique", "de": "Verlauf", "pt": "Histórico", "it": "Cronologia", "ja": "履歴", "zh": "历史", "hi": "इतिहास", "ar": "السجل"],
        "sfy.history.none": ["en": "Nothing has happened yet.", "es": "No ha pasado nada todavía.", "fr": "Rien ne s'est encore passé.", "de": "Bisher ist nichts geschehen.", "pt": "Ainda não aconteceu nada.", "it": "Non è ancora successo nulla.", "ja": "まだ何も起きていません。", "zh": "尚未发生任何事。", "hi": "अभी कुछ नहीं हुआ।", "ar": "لم يحدث شيء بعد."],
        "hld.plan": ["en": "Your plan", "es": "Tu plan", "fr": "Votre forfait", "de": "Ihr Tarif", "pt": "O seu plano", "it": "Il tuo piano", "ja": "あなたのプラン", "zh": "你的方案", "hi": "आपकी योजना", "ar": "خطتك"],
        "att.spec": ["en": "Specialists", "es": "Especialistas", "fr": "Spécialistes", "de": "Spezialisten", "pt": "Especialistas", "it": "Specialisti", "ja": "専門家", "zh": "专家", "hi": "विशेषज्ञ", "ar": "المتخصصون"],
        "att.spec.local": ["en": "Install the local set", "es": "Instalar el conjunto local", "fr": "Installer le jeu local", "de": "Lokales Set installieren", "pt": "Instalar o conjunto local", "it": "Installa il set locale", "ja": "ローカルセットを導入", "zh": "安装本地集合", "hi": "स्थानीय सेट स्थापित करें", "ar": "تثبيت المجموعة المحلية"],
        "att.spec.hosted": ["en": "Install the QRME-hosted set", "es": "Instalar el conjunto alojado en QRME", "fr": "Installer le jeu hébergé par QRME", "de": "Das QRME-gehostete Set installieren", "pt": "Instalar o conjunto alojado no QRME", "it": "Installa il set ospitato su QRME", "ja": "QRMEホストのセットを導入", "zh": "安装QRME托管集合", "hi": "QRME-होस्टेड सेट स्थापित करें", "ar": "تثبيت مجموعة QRME المستضافة"],
        "att.spec.none": ["en": "None installed. Without one, handing a thing over answers no tandem specialist and does nothing — a refusal, not a silent drop.", "es": "Ninguno instalado. Sin uno, entregar algo responde no hay especialista en tándem y no hace nada — un rechazo, no una omisión silenciosa.", "fr": "Aucun installé. Sans, confier une chose répond aucun spécialiste en tandem et ne fait rien — un refus, pas un abandon silencieux.", "de": "Keiner installiert. Ohne einen antwortet die Übergabe kein Tandem-Spezialist und tut nichts — eine Ablehnung, kein stilles Verschlucken.", "pt": "Nenhum instalado. Sem um, entregar algo responde nenhum especialista em tandem e não faz nada — uma recusa, não uma queda silenciosa.", "it": "Nessuno installato. Senza, consegnare qualcosa risponde nessuno specialista in tandem e non fa nulla — un rifiuto, non una caduta silenziosa.", "ja": "未導入です。ないまま引き渡すと「タンデム専門家なし」と答えて何もしません — 静かな握りつぶしではなく拒否です。", "zh": "尚未安装。没有它，移交会回答「无协作专家」且什么也不做 — 是拒绝，而非静默丢弃。", "hi": "कोई स्थापित नहीं। इसके बिना, सौंपने पर जवाब मिलता है कोई टैंडम विशेषज्ञ नहीं और कुछ नहीं होता — इनकार, चुपचाप गिराना नहीं।", "ar": "لا شيء مثبت. بدونه، يجيب التسليم لا متخصص مرافق ولا يفعل شيئًا — رفض لا إسقاط صامت."],
        "att.hand": ["en": "Hand something over", "es": "Entregar algo", "fr": "Confier quelque chose", "de": "Etwas übergeben", "pt": "Entregar algo", "it": "Consegna qualcosa", "ja": "何かを引き渡す", "zh": "移交事项", "hi": "कुछ सौंपें", "ar": "سلّم شيئًا"],
        "att.hand.ph": ["en": "Get through the week", "es": "Superar la semana", "fr": "Tenir la semaine", "de": "Die Woche überstehen", "pt": "Aguentar a semana", "it": "Superare la settimana", "ja": "今週を乗り切る", "zh": "撑过这一周", "hi": "यह हफ़्ता पार करें", "ar": "اجتياز الأسبوع"],
        "att.hand.go": ["en": "Hand it over", "es": "Entregarlo", "fr": "Le confier", "de": "Übergeben", "pt": "Entregar", "it": "Consegnalo", "ja": "引き渡す", "zh": "移交", "hi": "सौंप दें", "ar": "سلّمه"],
        "att.hand.who": ["en": "Who could see me for this?", "es": "¿Quién podría atenderme por esto?", "fr": "Qui pourrait me recevoir pour ça ?", "de": "Wer könnte mich damit sehen?", "pt": "Quem me poderia ver por isto?", "it": "Chi potrebbe vedermi per questo?", "ja": "これで診てくれるのは誰？", "zh": "这事谁能接诊我？", "hi": "इसके लिए मुझे कौन देख सकता है?", "ar": "من يمكنه استقبالي لهذا؟"],
