        "ns.dk.line": ["en": "{corner} · {state}{forced} · showing {face}", "es": "{corner} · {state}{forced} · mostrando {face}", "fr": "{corner} · {state}{forced} · affiche {face}", "de": "{corner} · {state}{forced} · zeigt {face}", "pt": "{corner} · {state}{forced} · a mostrar {face}", "it": "{corner} · {state}{forced} · mostra {face}", "ja": "{corner} · {state}{forced} · 表示中 {face}", "zh": "{corner} · {state}{forced} · 正在显示{face}", "hi": "{corner} · {state}{forced} · दिखा रहा {face}", "ar": "{corner} · {state}{forced} · يعرض {face}"],
