        "ns.ml.saved": ["en": "(saved — type to replace)", "es": "(guardada — escribe para reemplazar)", "fr": "(enregistré — tapez pour remplacer)", "de": "(gespeichert — tippen zum Ersetzen)", "pt": "(guardada — escreva para substituir)", "it": "(salvata — digita per sostituire)", "ja": "（保存済み — 入力すると置き換わります）", "zh": "（已保存 — 输入即替换）", "hi": "(सहेजा गया — बदलने के लिए टाइप करें)", "ar": "(محفوظة — اكتب للاستبدال)"],
