        "ns.ml.test": ["en": "Send a test message to", "es": "Enviar un mensaje de prueba a", "fr": "Envoyer un message de test à", "de": "Testnachricht senden an", "pt": "Enviar mensagem de teste para", "it": "Invia un messaggio di prova a", "ja": "テストメッセージの宛先", "zh": "发送测试邮件至", "hi": "परीक्षण संदेश भेजें", "ar": "أرسل رسالة اختبار إلى"],
        "ns.ml.test.ph": ["en": "you@example.com", "es": "tu@example.com", "fr": "vous@example.com", "de": "sie@example.com", "pt": "voce@example.com", "it": "tu@example.com", "ja": "you@example.com", "zh": "you@example.com", "hi": "aap@example.com", "ar": "you@example.com"],
        "ns.med.title": ["en": "Medications", "es": "Medicamentos", "fr": "Médicaments", "de": "Medikamente", "pt": "Medicamentos", "it": "Farmaci", "ja": "薬", "zh": "药物", "hi": "दवाइयाँ", "ar": "الأدوية"],
        "ns.med.missed": ["en": "⚠ {list} — marked critical and not logged today. If you took it, tap it below; if you didn't, that's worth a moment.", "es": "⚠ {list} — marcados como críticos y sin registrar hoy. Si lo tomaste, tócalo abajo; si no, merece un momento.", "fr": "⚠ {list} — marqués critiques et non consignés aujourd'hui. Si vous l'avez pris, touchez-le ci-dessous ; sinon, cela mérite un instant.", "de": "⚠ {list} — als kritisch markiert und heute nicht erfasst. Wenn Sie es genommen haben, tippen Sie unten darauf; wenn nicht, ist das einen Moment wert.", "pt": "⚠ {list} — marcados como críticos e não registados hoje. Se o tomou, toque abaixo; se não, isso merece um momento.", "it": "⚠ {list} — segnati come critici e non registrati oggi. Se l'hai preso, toccalo qui sotto; se no, vale un momento.", "ja": "⚠ {list} — 重要と設定されていますが、今日はまだ記録がありません。飲んだなら下でタップを、飲んでいないなら少し立ち止まる価値があります。", "zh": "⚠ {list} — 已标为关键，今天尚未记录。若你已服用，请在下方点选；若没有，这值得停下来想一想。", "hi": "⚠ {list} — महत्वपूर्ण चिह्नित है और आज दर्ज नहीं हुआ। अगर आपने लिया है तो नीचे टैप करें; नहीं लिया तो यह एक पल ठहरने लायक़ है।", "ar": "⚠ {list} — مُعلَّم كحرج ولم يُسجَّل اليوم. إن كنت تناولته فانقره أدناه؛ وإن لم تفعل، فالأمر يستحق لحظة."],
        "ns.med.today": ["en": "Today", "es": "Hoy", "fr": "Aujourd'hui", "de": "Heute", "pt": "Hoje", "it": "Oggi", "ja": "今日", "zh": "今天", "hi": "आज", "ar": "اليوم"],
        "ns.med.none": ["en": "Nothing here yet — add what you take below, in your own words.", "es": "Aquí no hay nada todavía — añade abajo lo que tomas, con tus palabras.", "fr": "Rien ici pour l'instant — ajoutez ci-dessous ce que vous prenez, avec vos mots.", "de": "Hier ist noch nichts — fügen Sie unten hinzu, was Sie nehmen, in Ihren eigenen Worten.", "pt": "Ainda não há nada aqui — adicione abaixo o que toma, nas suas palavras.", "it": "Qui non c'è ancora niente — aggiungi sotto ciò che prendi, con parole tue.", "ja": "まだ何もありません — 服用しているものを、自分の言葉で下に追加してください。", "zh": "这里还什么都没有 — 在下方用你自己的话添加你所服用的药。", "hi": "यहाँ अभी कुछ नहीं — नीचे अपने शब्दों में जोड़ें कि आप क्या लेते हैं।", "ar": "لا شيء هنا بعد — أضف أدناه ما تتناوله، بكلماتك أنت."],
        "ns.med.stop": ["en": "stop", "es": "dejar", "fr": "arrêter", "de": "beenden", "pt": "parar", "it": "smetti", "ja": "中止", "zh": "停止", "hi": "रोकें", "ar": "أوقف"],
        "ns.med.take": ["en": "Take", "es": "Tomar", "fr": "Prendre", "de": "Nehmen", "pt": "Tomar", "it": "Prendi", "ja": "服用", "zh": "服用", "hi": "लें", "ar": "تناول"],
