        "ns.med.add": ["en": "Add a medication", "es": "Añadir un medicamento", "fr": "Ajouter un médicament", "de": "Ein Medikament hinzufügen", "pt": "Adicionar um medicamento", "it": "Aggiungi un farmaco", "ja": "薬を追加", "zh": "添加一种药", "hi": "दवा जोड़ें", "ar": "أضف دواءً"],
        "ns.med.add.pitch": ["en": "Your words are fine — “the little white one, 10 mg” is a valid name and dose.", "es": "Tus palabras valen — «la blanquita, 10 mg» es un nombre y una dosis válidos.", "fr": "Vos mots suffisent — « le petit blanc, 10 mg » est un nom et une dose valables.", "de": "Ihre Worte genügen — »die kleine weiße, 10 mg« ist ein gültiger Name und eine gültige Dosis.", "pt": "As suas palavras servem — «o branquinho, 10 mg» é um nome e uma dose válidos.", "it": "Le tue parole vanno bene — «quella bianca piccola, 10 mg» è un nome e una dose validi.", "ja": "あなたの言葉で構いません — 「小さい白いの、10 mg」も立派な名前と用量です。", "zh": "用你自己的话就好 — 「那个白色小药片，10 mg」就是有效的名称和剂量。", "hi": "आपके शब्द ठीक हैं — «वो छोटी सफ़ेद वाली, 10 mg» एक मान्य नाम और ख़ुराक है।", "ar": "كلماتك تكفي — «الحبة البيضاء الصغيرة، 10 ملغ» اسم وجرعة صالحان."],
        "ns.med.name": ["en": "Name", "es": "Nombre", "fr": "Nom", "de": "Name", "pt": "Nome", "it": "Nome", "ja": "名前", "zh": "名称", "hi": "नाम", "ar": "الاسم"],
        "ns.med.name.ph": ["en": "Lisinopril", "es": "Lisinopril", "fr": "Lisinopril", "de": "Lisinopril", "pt": "Lisinopril", "it": "Lisinopril", "ja": "Lisinopril", "zh": "Lisinopril", "hi": "Lisinopril", "ar": "Lisinopril"],
