        "ns.med.purpose": ["en": "What it's for", "es": "Para qué es", "fr": "À quoi ça sert", "de": "Wofür es ist", "pt": "Para que serve", "it": "A cosa serve", "ja": "何のための薬か", "zh": "用来治什么", "hi": "यह किसलिए है", "ar": "لماذا هو"],
        "ns.med.purpose.ph": ["en": "blood pressure", "es": "tensión arterial", "fr": "tension artérielle", "de": "Blutdruck", "pt": "tensão arterial", "it": "pressione sanguigna", "ja": "血圧", "zh": "血压", "hi": "रक्तचाप", "ar": "ضغط الدم"],
        "ns.med.asneeded": ["en": "As needed, not on a schedule", "es": "Según necesidad, sin horario", "fr": "Au besoin, pas selon un horaire", "de": "Bei Bedarf, nicht nach Plan", "pt": "Conforme necessário, sem horário", "it": "Al bisogno, non a orario", "ja": "定時ではなく頓用", "zh": "按需服用，非定时", "hi": "आवश्यकतानुसार, समय-सारणी पर नहीं", "ar": "عند الحاجة، لا وفق جدول"],
        "ns.med.ceiling": ["en": "Ceiling per day", "es": "Máximo por día", "fr": "Plafond par jour", "de": "Obergrenze pro Tag", "pt": "Limite por dia", "it": "Tetto giornaliero", "ja": "1日の上限", "zh": "每日上限", "hi": "प्रतिदिन अधिकतम", "ar": "الحد اليومي"],
        "ns.med.ceiling.note": ["en": "(optional — JIM will refuse to log past it)", "es": "(opcional — JIM se negará a registrar por encima)", "fr": "(facultatif — JIM refusera d'enregistrer au-delà)", "de": "(optional — JIM verweigert Einträge darüber hinaus)", "pt": "(opcional — o JIM recusará registar acima disso)", "it": "(facoltativo — JIM rifiuterà di registrare oltre)", "ja": "（任意 — これを超える記録をJIMは拒みます）", "zh": "（可选 — 超过后 JIM 会拒绝记录）", "hi": "(वैकल्पिक — इससे आगे JIM दर्ज करने से मना कर देगा)", "ar": "(اختياري — سيرفض JIM التسجيل بعده)"],
        "ns.med.times": ["en": "Times", "es": "Horas", "fr": "Heures", "de": "Zeiten", "pt": "Horas", "it": "Orari", "ja": "時刻", "zh": "时间", "hi": "समय", "ar": "الأوقات"],
        "ns.med.times.note": ["en": "— comma-separated, 24h", "es": "— separadas por comas, 24 h", "fr": "— séparées par des virgules, format 24 h", "de": "— kommagetrennt, 24 h", "pt": "— separadas por vírgulas, 24 h", "it": "— separati da virgole, 24 h", "ja": "— カンマ区切り、24時間表記", "zh": "— 逗号分隔，24小时制", "hi": "— अल्पविराम से अलग, 24 घंटे", "ar": "— مفصولة بفواصل، بنظام 24 ساعة"],
        "ns.med.critical": ["en": "Missing this one is worth a check-in", "es": "Saltarse este merece una consulta", "fr": "Manquer celui-ci mérite qu'on prenne de vos nouvelles", "de": "Dieses zu verpassen ist eine Nachfrage wert", "pt": "Falhar este merece uma verificação", "it": "Saltare questo vale un controllo", "ja": "これを飲み忘れたら声をかけてほしい", "zh": "漏服这一种值得来问一句", "hi": "यह छूटे तो हालचाल पूछना बनता है", "ar": "تفويت هذا يستحق اطمئنانًا"],
        "ns.vg.title": ["en": "The vigil", "es": "La vigilia", "fr": "La veille", "de": "Die Wache", "pt": "A vigília", "it": "La veglia", "ja": "見守り", "zh": "守夜", "hi": "पहरा", "ar": "السهر"],
        "ns.vg.pitch": ["en": "Every other alarm fires on a reading. This one fires on the absence of readings: name someone, and if nothing is heard from you for longer than the quiet period, they are asked to check on you. Any reading stands it down. It never calls emergency services — it knocks on a door.", "es": "Todas las demás alarmas se disparan por una lectura. Esta se dispara por la ausencia de lecturas: nombra a alguien, y si no se sabe nada de ti durante más tiempo que el periodo de silencio, se le pide que vaya a ver cómo estás. Cualquier lectura la desactiva. Nunca llama a los servicios de emergencia — llama a una puerta.", "fr": "Toutes les autres alertes se déclenchent sur une mesure. Celle-ci se déclenche sur l'absence de mesures : nommez quelqu'un, et si l'on n'a rien de vous plus longtemps que la période de silence, on lui demande de prendre de vos nouvelles. Toute mesure la lève. Elle n'appelle jamais les secours — elle frappe à une porte.", "de": "Jeder andere Alarm löst auf eine Messung hin aus. Dieser löst auf das Ausbleiben von Messungen hin aus: nennen Sie jemanden, und hört man länger als die Stillperiode nichts von Ihnen, wird diese Person gebeten, nach Ihnen zu sehen. Jede Messung stellt ihn zurück. Er ruft nie den Rettungsdienst — er klopft an eine Tür.", "pt": "Todos os outros alarmes disparam com uma leitura. Este dispara com a ausência de leituras: nomeie alguém, e se nada se souber de si por mais tempo do que o período de silêncio, pedem-lhe que veja como está. Qualquer leitura o desativa. Nunca chama os serviços de emergência — bate a uma porta.", "it": "Ogni altro allarme scatta su una lettura. Questo scatta sull'assenza di letture: nomina qualcuno, e se non si sa nulla di te per più del periodo di silenzio, gli si chiede di venire a vedere come stai. Qualsiasi lettura lo rientra. Non chiama mai i soccorsi — bussa a una porta.", "ja": "他のあらゆる警報は測定値によって鳴ります。これは測定値がないことによって鳴ります：誰かを指名しておくと、静穏期間を超えてあなたから何の知らせもない場合、その人に様子を見に行くよう頼まれます。どんな測定値でも解除されます。救急を呼ぶことは決してなく — 扉を叩くだけです。", "zh": "其他所有警报都因某条读数而触发。这一个因读数的缺席而触发：指定一个人，若超过静默期仍未收到你的任何消息，就会请他来看看你。任何读数都会将其解除。它绝不呼叫急救 — 它只是去敲一扇门。", "hi": "बाक़ी हर अलार्म किसी रीडिंग पर बजता है। यह रीडिंग की अनुपस्थिति पर बजता है: किसी का नाम दें, और यदि शांत अवधि से अधिक समय तक आपका कोई हाल न मिले, तो उनसे आपकी ख़बर लेने को कहा जाता है। कोई भी रीडिंग इसे शांत कर देती है। यह कभी आपातकालीन सेवाएँ नहीं बुलाता — यह एक दरवाज़ा खटखटाता है।", "ar": "كل إنذار آخر ينطلق بقراءة. هذا ينطلق بغياب القراءات: سمِّ شخصًا، وإن لم يُسمع عنك شيء أطول من فترة الصمت، يُطلب منه أن يطمئن عليك. وأي قراءة تُعيده. لا يستدعي الطوارئ أبدًا — بل يطرق بابًا."],
        "ns.vg.tripped": ["en": "⚠ The vigil has tripped — {name} was asked to check on you{after}.", "es": "⚠ La vigilia se ha disparado — se pidió a {name} que fuera a ver cómo estás{after}.", "fr": "⚠ La veille s'est déclenchée — on a demandé à {name} de prendre de vos nouvelles{after}.", "de": "⚠ Die Wache hat ausgelöst — {name} wurde gebeten, nach Ihnen zu sehen{after}.", "pt": "⚠ A vigília disparou — pediram a {name} que visse como está{after}.", "it": "⚠ La veglia è scattata — è stato chiesto a {name} di venire a vedere come stai{after}.", "ja": "⚠ 見守りが作動しました — {name}にあなたの様子を見るよう依頼しました{after}。", "zh": "⚠ 守夜已触发 — 已请{name}来看看你{after}。", "hi": "⚠ पहरा सक्रिय हुआ — {name} से आपकी ख़बर लेने को कहा गया{after}।", "ar": "⚠ انطلق السهر — طُلب من {name} أن يطمئن عليك{after}."],
        "ns.vg.after": ["en": " after {n} quiet days", "es": " tras {n} días de silencio", "fr": " après {n} jours de silence", "de": " nach {n} stillen Tagen", "pt": " após {n} dias de silêncio", "it": " dopo {n} giorni di silenzio", "ja": "（静穏{n}日ののち）", "zh": "（在{n}天静默之后）", "hi": " {n} शांत दिनों के बाद", "ar": " بعد {n} أيام من الصمت"],
        "ns.vg.okay": ["en": "I'm okay", "es": "Estoy bien", "fr": "Ça va", "de": "Mir geht es gut", "pt": "Estou bem", "it": "Sto bene", "ja": "大丈夫です", "zh": "我没事", "hi": "मैं ठीक हूँ", "ar": "أنا بخير"],
        "ns.vg.name": ["en": "Steward's name", "es": "Nombre de la persona de guardia", "fr": "Nom de la personne de confiance", "de": "Name des Verwalters", "pt": "Nome do guardião", "it": "Nome del custode", "ja": "見守り役の名前", "zh": "受托人姓名", "hi": "संरक्षक का नाम", "ar": "اسم القيّم"],
        "ns.vg.name.ph": ["en": "Who to tell", "es": "A quién avisar", "fr": "Qui prévenir", "de": "Wem Bescheid geben", "pt": "A quem avisar", "it": "Chi avvisare", "ja": "誰に知らせるか", "zh": "该通知谁", "hi": "किसे बताना है", "ar": "من تُخبر"],
        "ns.vg.reach": ["en": "How to reach them", "es": "Cómo contactarle", "fr": "Comment la joindre", "de": "Wie man sie erreicht", "pt": "Como contactá-lo", "it": "Come raggiungerlo", "ja": "連絡方法", "zh": "如何联系", "hi": "उन तक कैसे पहुँचें", "ar": "كيف تصل إليه"],
        "ns.vg.reach.ph": ["en": "their@email.com", "es": "su@email.com", "fr": "son@email.com", "de": "ihre@email.com", "pt": "dele@email.com", "it": "suo@email.com", "ja": "their@email.com", "zh": "their@email.com", "hi": "unka@email.com", "ar": "their@email.com"],
        "ns.vg.days": ["en": "Quiet days before they're told", "es": "Días de silencio antes de avisarle", "fr": "Jours de silence avant qu'on la prévienne", "de": "Stille Tage, bevor Bescheid gegeben wird", "pt": "Dias de silêncio antes de o avisarem", "it": "Giorni di silenzio prima di avvisarlo", "ja": "知らせるまでの静穏日数", "zh": "通知前的静默天数", "hi": "बताने से पहले शांत दिन", "ar": "أيام الصمت قبل إخباره"],
        "ns.vg.words": ["en": "In your own words", "es": "Con tus palabras", "fr": "Avec vos mots", "de": "In Ihren eigenen Worten", "pt": "Nas suas palavras", "it": "Con parole tue", "ja": "自分の言葉で", "zh": "用你自己的话", "hi": "अपने शब्दों में", "ar": "بكلماتك أنت"],
        "ns.vg.words.note": ["en": "— what they'll read, written now", "es": "— lo que leerá, escrito ahora", "fr": "— ce qu'elle lira, écrit maintenant", "de": "— was sie lesen wird, jetzt geschrieben", "pt": "— o que ele lerá, escrito agora", "it": "— ciò che leggerà, scritto ora", "ja": "— その人が読む言葉を、いま書いておく", "zh": "— 他将读到的内容，此刻写下", "hi": "— वे क्या पढ़ेंगे, अभी लिखा हुआ", "ar": "— ما سيقرؤه، مكتوبًا الآن"],
        "ns.vg.words.ph": ["en": "I live alone — please knock.", "es": "Vivo solo — llama a la puerta, por favor.", "fr": "Je vis seul — frappez, s'il vous plaît.", "de": "Ich lebe allein — bitte klopfen Sie.", "pt": "Vivo sozinho — por favor bata à porta.", "it": "Vivo da solo — bussa, per favore.", "ja": "一人暮らしです — どうか扉を叩いてください。", "zh": "我独自居住 — 请敲门。", "hi": "मैं अकेला रहता हूँ — कृपया दरवाज़ा खटखटाएँ।", "ar": "أعيش وحدي — من فضلك اطرق الباب."],
        "ns.vg.disarm": ["en": "Disarm", "es": "Desactivar", "fr": "Désarmer", "de": "Entschärfen", "pt": "Desarmar", "it": "Disattiva", "ja": "解除する", "zh": "停用", "hi": "निष्क्रिय करें", "ar": "ألغِ التفعيل"],
        "ns.vg.check": ["en": "Just check it", "es": "Solo comprobarla", "fr": "Juste vérifier", "de": "Nur nachsehen", "pt": "Só verificar", "it": "Solo controlla", "ja": "確認するだけ", "zh": "只查看", "hi": "बस जाँच लें", "ar": "تفقّده فقط"],
        "ns.vg.armed": ["en": "Armed · last heard from you {when} · steward: {name}", "es": "Activada · última señal tuya {when} · persona de guardia: {name}", "fr": "Armée · dernières nouvelles de vous {when} · personne de confiance : {name}", "de": "Scharf · zuletzt von Ihnen gehört {when} · Verwalter: {name}", "pt": "Ativada · última notícia sua {when} · guardião: {name}", "it": "Attiva · ultime tue notizie {when} · custode: {name}", "ja": "作動中 · 最後の便り {when} · 見守り役: {name}", "zh": "已启用 · 最近一次得知你的消息 {when} · 受托人: {name}", "hi": "सक्रिय · आपकी अंतिम ख़बर {when} · संरक्षक: {name}", "ar": "مفعّل · آخر خبر عنك {when} · القيّم: {name}"],
        "ns.bas.title": ["en": "Your baseline", "es": "Tu línea base", "fr": "Votre ligne de base", "de": "Ihre Basislinie", "pt": "A sua linha de base", "it": "La tua linea di base", "ja": "あなたのベースライン", "zh": "你的基线", "hi": "आपकी आधार रेखा", "ar": "خطك الأساسي"],
        "ns.bas.sub": ["en": "The widths below are yours to set. Narrow one to be told sooner; widen it if a metric of yours naturally wanders.", "es": "Los anchos de abajo los fijas tú. Estrecha uno para enterarte antes; ensánchalo si una métrica tuya vaga por naturaleza.", "fr": "Les largeurs ci-dessous sont à vous. Resserrez-en une pour être prévenu plus tôt ; élargissez-la si une de vos métriques vagabonde naturellement.", "de": "Die Breiten darunter bestimmen Sie. Verengen Sie eine, um früher Bescheid zu bekommen; weiten Sie sie, wenn eine Ihrer Metriken von Natur aus wandert.", "pt": "As larguras abaixo são suas. Estreite uma para saber mais cedo; alargue-a se uma métrica sua vagueia por natureza.", "it": "Le larghezze qui sotto le decidi tu. Restringine una per saperlo prima; allargala se una tua metrica vaga per natura.", "ja": "下の幅はあなたが決めます。早く知りたければ狭く、生まれつき揺れやすい指標なら広く。", "zh": "下面的宽度由你设定。调窄可更早得知；某项指标天生爱漂移就调宽。", "hi": "नीचे की चौड़ाइयाँ आप तय करते हैं। जल्दी जानने के लिए संकरी करें; अगर आपका कोई मीट्रिक स्वभावतः भटकता है तो चौड़ी करें।", "ar": "العروض أدناه أنت من يحددها. ضيّق نطاقًا لتُخبَر أبكر؛ ووسّعه إن كان أحد مقاييسك يتجول بطبيعته."],
        "ns.bas.none": ["en": "Nothing yet.", "es": "Todavía nada.", "fr": "Rien pour l'instant.", "de": "Noch nichts.", "pt": "Ainda nada.", "it": "Ancora niente.", "ja": "まだ何もありません。", "zh": "暂时还没有。", "hi": "अभी कुछ नहीं।", "ar": "لا شيء بعد."],
        "ns.bas.learning": ["en": "learning — {n} resting readings so far", "es": "aprendiendo — {n} lecturas en reposo hasta ahora", "fr": "apprentissage — {n} mesures au repos pour l'instant", "de": "lernt — bisher {n} Ruhemessungen", "pt": "a aprender — {n} leituras em repouso até agora", "it": "in apprendimento — {n} letture a riposo finora", "ja": "学習中 — これまでの安静時測定{n}件", "zh": "学习中 — 目前{n}条静息读数", "hi": "सीख रहा है — अब तक {n} विश्राम रीडिंग", "ar": "قيد التعلم — {n} قراءات راحة حتى الآن"],
        "ns.bas.usual": ["en": "your usual {v}, checked in below {lo} or above {hi}", "es": "tu habitual {v}, se consulta por debajo de {lo} o por encima de {hi}", "fr": "votre habituel {v}, contrôle sous {lo} ou au-dessus de {hi}", "de": "Ihr üblicher Wert {v}, nachgefragt unter {lo} oder über {hi}", "pt": "o seu habitual {v}, verificado abaixo de {lo} ou acima de {hi}", "it": "il tuo solito {v}, controllo sotto {lo} o sopra {hi}", "ja": "普段は{v}、{lo}未満または{hi}超で確認します", "zh": "你的常态{v}，低于{lo}或高于{hi}时问询", "hi": "आपका सामान्य {v}, {lo} से नीचे या {hi} से ऊपर पर पूछा जाता है", "ar": "معتادك {v}، يُسأل دون {lo} أو فوق {hi}"],
        "ns.bas.drop": ["en": "tell me when it drops", "es": "avísame cuando baje", "fr": "prévenez-moi quand ça baisse", "de": "sag mir, wenn es fällt", "pt": "avisa-me quando descer", "it": "dimmi quando scende", "ja": "下がったら知らせて", "zh": "下降时告诉我", "hi": "गिरे तो बताएँ", "ar": "أخبرني إذا انخفض"],
        "ns.bas.climb": ["en": "tell me when it climbs", "es": "avísame cuando suba", "fr": "prévenez-moi quand ça monte", "de": "sag mir, wenn es steigt", "pt": "avisa-me quando subir", "it": "dimmi quando sale", "ja": "上がったら知らせて", "zh": "上升时告诉我", "hi": "चढ़े तो बताएँ", "ar": "أخبرني إذا ارتفع"],
        "ns.bas.reset": ["en": "Reset", "es": "Restablecer", "fr": "Réinitialiser", "de": "Zurücksetzen", "pt": "Repor", "it": "Reimposta", "ja": "リセット", "zh": "重置", "hi": "रीसेट", "ar": "إعادة ضبط"],
        "ns.vg.arm": ["en": "Arm the vigil", "es": "Activar la vigilia", "fr": "Armer la veille", "de": "Die Wache scharf stellen", "pt": "Armar a vigília", "it": "Attiva la veglia", "ja": "見守りを有効にする", "zh": "开启守夜", "hi": "पहरा सक्रिय करें", "ar": "تفعيل السهر"],
        "ns.vg.update": ["en": "Update the vigil", "es": "Actualizar la vigilia", "fr": "Mettre à jour la veille", "de": "Die Wache aktualisieren", "pt": "Atualizar a vigília", "it": "Aggiorna la veglia", "ja": "見守りを更新する", "zh": "更新守夜", "hi": "पहरा अद्यतन करें", "ar": "تحديث السهر"],
        "ns.acc.needs.title": ["en": "Who is expected here", "es": "A quién esperamos aquí", "fr": "Qui est attendu ici", "de": "Wer hier erwartet wird", "pt": "Quem é esperado aqui", "it": "Chi è atteso qui", "ja": "ここに来ることが想定されている人", "zh": "这里期待谁的到来", "hi": "यहाँ किनकी अपेक्षा है", "ar": "من ننتظر هنا"],
        "ns.acc.needs.blind": ["en": "Blind and low-vision: every function works by text, images carry descriptions, and the screens use standard controls a screen reader can walk.", "es": "Personas ciegas o con baja visión: cada función opera por texto, las imágenes llevan descripciones y las pantallas usan controles estándar que un lector de pantalla puede recorrer.", "fr": "Personnes aveugles ou malvoyantes : chaque fonction passe par le texte, les images portent des descriptions et les écrans utilisent des contrôles standard qu’un lecteur d’écran peut parcourir.", "de": "Blinde und sehbehinderte Menschen: jede Funktion geht über Text, Bilder tragen Beschreibungen, und die Oberfläche nutzt Standard-Elemente, die ein Screenreader ablaufen kann.", "pt": "Pessoas cegas ou com baixa visão: toda função opera por texto, as imagens têm descrições e as telas usam controles padrão que um leitor de tela consegue percorrer.", "it": "Persone cieche o ipovedenti: ogni funzione passa dal testo, le immagini hanno descrizioni e le schermate usano controlli standard che uno screen reader può percorrere.", "ja": "全盲・弱視の方：すべての機能はテキストで使え、画像には説明が付き、画面はスクリーンリーダーがたどれる標準コントロールでできています。", "zh": "盲人和低视力者：一切功能都可通过文字完成，图像带有描述，界面使用屏幕阅读器可以遍历的标准控件。", "hi": "दृष्टिहीन और कम दृष्टि वाले: हर कार्य पाठ से होता है, चित्रों के साथ विवरण है, और स्क्रीन में मानक नियंत्रण हैं जिन्हें स्क्रीन रीडर पढ़ सकता है।", "ar": "المكفوفون وضعاف البصر: كل وظيفة تعمل بالنص، والصور تحمل أوصافًا، والشاشات تستخدم عناصر قياسية يستطيع قارئ الشاشة تتبعها."],
        "ns.acc.needs.deaf": ["en": "Deaf and hard of hearing: nothing here requires sound — voice is always optional, never the only way.", "es": "Personas sordas o con pérdida auditiva: nada aquí requiere sonido; la voz es siempre opcional, nunca el único camino.", "fr": "Personnes sourdes ou malentendantes : rien ici n’exige de son — la voix est toujours facultative, jamais le seul chemin.", "de": "Gehörlose und schwerhörige Menschen: nichts hier verlangt Ton — Sprache ist immer optional, nie der einzige Weg.", "pt": "Pessoas surdas ou com perda auditiva: nada aqui exige som — a voz é sempre opcional, nunca o único caminho.", "it": "Persone sorde o con perdita d’udito: niente qui richiede l’audio — la voce è sempre facoltativa, mai l’unica via.", "ja": "ろう・難聴の方：ここでは音を必要とするものはありません。音声は常に任意で、唯一の手段になることはありません。", "zh": "聋人和听障者：这里没有任何功能依赖声音——语音永远是可选的，绝不是唯一途径。", "hi": "बधिर और कम सुनने वाले: यहाँ किसी चीज़ के लिए ध्वनि आवश्यक नहीं — आवाज़ हमेशा वैकल्पिक है, कभी एकमात्र रास्ता नहीं।", "ar": "الصم وضعاف السمع: لا شيء هنا يتطلب صوتًا — الصوت اختياري دائمًا، وليس الطريق الوحيد أبدًا."],
        "ns.acc.needs.mute": ["en": "Mute and nonspeaking: nothing here requires speaking — anywhere a microphone is offered, typing does the same job.", "es": "Personas mudas o que no hablan: nada aquí requiere hablar; donde se ofrece un micrófono, escribir hace el mismo trabajo.", "fr": "Personnes muettes ou non verbales : rien ici n’exige de parler — partout où un micro est proposé, écrire fait le même travail.", "de": "Stumme und nicht sprechende Menschen: nichts hier verlangt Sprechen — überall, wo ein Mikrofon angeboten wird, tut Tippen denselben Dienst.", "pt": "Pessoas mudas ou não falantes: nada aqui exige falar — onde houver microfone, digitar faz o mesmo trabalho.", "it": "Persone mute o non parlanti: niente qui richiede di parlare — ovunque ci sia un microfono, scrivere fa lo stesso lavoro.", "ja": "発話しない方・発話が難しい方：ここでは話すことを必要とするものはありません。マイクがある場所ではどこでも、入力が同じ役割を果たします。", "zh": "失语和不说话的人：这里没有任何功能要求开口——凡是提供麦克风的地方，打字都能完成同样的事。", "hi": "मूक और न बोलने वाले: यहाँ बोलना आवश्यक नहीं — जहाँ भी माइक्रोफ़ोन है, वहाँ टाइप करना वही काम करता है।", "ar": "البُكم ومن لا يتكلمون: لا شيء هنا يتطلب الكلام — أينما وُجد ميكروفون، تقوم الكتابة بالمهمة نفسها."],
        "ns.acc.needs.motor": ["en": "Limited mobility, amputation, tremor: every control is a standard element the keyboard alone can reach, and no step in this console is timed.", "es": "Movilidad reducida, amputación, temblor: cada control es un elemento estándar alcanzable solo con el teclado, y ningún paso de esta consola tiene límite de tiempo.", "fr": "Mobilité réduite, amputation, tremblement : chaque contrôle est un élément standard atteignable au clavier seul, et aucune étape de cette console n’est chronométrée.", "de": "Eingeschränkte Mobilität, Amputation, Tremor: jedes Element ist ein Standard-Element, das die Tastatur allein erreicht, und kein Schritt in dieser Konsole hat ein Zeitlimit.", "pt": "Mobilidade reduzida, amputação, tremor: todo controle é um elemento padrão alcançável só pelo teclado, e nenhum passo neste console é cronometrado.", "it": "Mobilità ridotta, amputazione, tremore: ogni controllo è un elemento standard raggiungibile con la sola tastiera, e nessun passaggio in questa console è a tempo.", "ja": "運動機能の制約・切断・振戦のある方：すべてのコントロールはキーボードだけで届く標準要素で、このコンソールに制限時間のある操作はありません。", "zh": "行动不便、截肢、震颤者：每个控件都是仅用键盘即可到达的标准元素，本控制台没有任何限时步骤。", "hi": "सीमित गतिशीलता, अंग-विच्छेद, कंपन: हर नियंत्रण एक मानक तत्व है जिस तक केवल कीबोर्ड से पहुँचा जा सकता है, और इस कंसोल में कोई चरण समयबद्ध नहीं है।", "ar": "محدودية الحركة والبتر والرُعاش: كل عنصر تحكم قياسي تصل إليه لوحة المفاتيح وحدها، ولا خطوة في هذه الواجهة مقيدة بوقت."],
        "ns.acc.needs.cognitive": ["en": "Autistic and cognitively different people: plain words, one step at a time, nothing flashes, and asking again is always free.", "es": "Personas autistas y cognitivamente diversas: palabras llanas, un paso a la vez, nada parpadea, y volver a preguntar es siempre gratis.", "fr": "Personnes autistes et cognitivement différentes : des mots simples, une étape à la fois, rien ne clignote, et redemander est toujours gratuit.", "de": "Autistische und kognitiv verschiedene Menschen: einfache Worte, ein Schritt nach dem anderen, nichts blinkt, und noch einmal fragen kostet nie etwas.", "pt": "Pessoas autistas e cognitivamente diversas: palavras simples, um passo de cada vez, nada pisca, e perguntar de novo é sempre grátis.", "it": "Persone autistiche e cognitivamente diverse: parole semplici, un passo alla volta, niente lampeggia, e chiedere di nuovo non costa mai nulla.", "ja": "自閉スペクトラムの方・認知の仕方が異なる方：平易な言葉、一度にひとつの手順、点滅するものはなく、もう一度尋ねることはいつでも自由です。", "zh": "自闭症和认知方式不同的人：语言平实，一次一步，没有闪烁的内容，再问一遍永远无妨。", "hi": "ऑटिस्टिक और संज्ञानात्मक रूप से भिन्न लोग: सरल शब्द, एक समय में एक कदम, कुछ नहीं चमकता, और दोबारा पूछना हमेशा निःशुल्क है।", "ar": "المصابون بالتوحد والمختلفون إدراكيًا: كلمات بسيطة، خطوة واحدة في كل مرة، لا شيء يومض، والسؤال مرة أخرى مجاني دائمًا."],
        "ns.acc.needs.dyslexia": ["en": "Dyslexia and reading differences: short sentences, real headings, and nothing that punishes rereading.", "es": "Dislexia y diferencias de lectura: frases cortas, encabezados reales y nada que castigue releer.", "fr": "Dyslexie et différences de lecture : phrases courtes, vrais titres, et rien qui punisse la relecture.", "de": "Dyslexie und Leseunterschiede: kurze Sätze, echte Überschriften, und nichts bestraft erneutes Lesen.", "pt": "Dislexia e diferenças de leitura: frases curtas, títulos de verdade e nada que puna reler.", "it": "Dislessia e differenze di lettura: frasi brevi, titoli veri e niente che punisca il rileggere.", "ja": "ディスレクシア・読み方の異なる方：短い文、本物の見出し、読み返しても不利にならない画面。", "zh": "阅读障碍者：短句、真实的标题，重读不会受到任何惩罚。", "hi": "डिस्लेक्सिया और पढ़ने की भिन्नताएँ: छोटे वाक्य, वास्तविक शीर्षक, और दोबारा पढ़ने पर कोई दंड नहीं।", "ar": "عسر القراءة وفروق القراءة: جمل قصيرة وعناوين حقيقية ولا شيء يعاقب على إعادة القراءة."],
        "ns.acc.needs.motion": ["en": "Motion sensitivity: when your device asks for reduced motion, this console stops animating.", "es": "Sensibilidad al movimiento: cuando tu dispositivo pide movimiento reducido, esta consola deja de animar.", "fr": "Sensibilité au mouvement : quand votre appareil demande une animation réduite, cette console cesse d’animer.", "de": "Bewegungsempfindlichkeit: wenn dein Gerät reduzierte Bewegung verlangt, hört diese Konsole auf zu animieren.", "pt": "Sensibilidade a movimento: quando seu dispositivo pede movimento reduzido, este console para de animar.", "it": "Sensibilità al movimento: quando il tuo dispositivo chiede movimento ridotto, questa console smette di animare.", "ja": "動きに敏感な方：端末が「視差効果を減らす」を求めると、このコンソールはアニメーションを止めます。", "zh": "对动态敏感者：当你的设备要求减少动态效果时，本控制台会停止动画。", "hi": "गति के प्रति संवेदनशीलता: जब आपका उपकरण कम गति माँगता है, यह कंसोल एनिमेशन बंद कर देता है।", "ar": "الحساسية للحركة: عندما يطلب جهازك تقليل الحركة، تتوقف هذه الواجهة عن التحريك."],
        "ns.acc.needs.more": ["en": "Not on this list? The gap is in the list, not in you. Name it below and it becomes our work.", "es": "¿No estás en esta lista? El vacío está en la lista, no en ti. Nómbralo abajo y se convierte en nuestro trabajo.", "fr": "Pas sur cette liste ? Le manque est dans la liste, pas en vous. Nommez-le ci-dessous et cela devient notre travail.", "de": "Nicht auf dieser Liste? Die Lücke ist in der Liste, nicht in dir. Benenne sie unten, und sie wird unsere Arbeit.", "pt": "Não está nesta lista? A lacuna está na lista, não em você. Nomeie-a abaixo e ela vira nosso trabalho.", "it": "Non sei in questa lista? La lacuna è nella lista, non in te. Nominala qui sotto e diventa il nostro lavoro.", "ja": "この一覧にありませんか？足りないのは一覧であって、あなたではありません。下で名前を付けてください。それが私たちの仕事になります。", "zh": "不在这份清单上？缺的是清单，不是你。在下方写出来，它就成为我们的工作。", "hi": "इस सूची में नहीं हैं? कमी सूची में है, आप में नहीं। नीचे उसे नाम दें और वह हमारा काम बन जाएगा।", "ar": "لست في هذه القائمة؟ النقص في القائمة لا فيك. اذكره أدناه وسيصبح عملنا."],
        "ns.acc.doing.ph": ["en": "What were you trying to do?", "es": "¿Qué intentabas hacer?", "fr": "Qu’essayiez-vous de faire ?", "de": "Was hast du versucht zu tun?", "pt": "O que você estava tentando fazer?", "it": "Cosa stavi cercando di fare?", "ja": "何をしようとしていましたか？", "zh": "你当时想做什么？", "hi": "आप क्या करने की कोशिश कर रहे थे?", "ar": "ما الذي كنت تحاول فعله؟"],
        "ns.acc.wall.ph": ["en": "What stood in the way?", "es": "¿Qué se interpuso?", "fr": "Qu’est-ce qui a fait obstacle ?", "de": "Was stand im Weg?", "pt": "O que ficou no caminho?", "it": "Cosa ti ha ostacolato?", "ja": "何が妨げになりましたか？", "zh": "是什么挡住了你？", "hi": "क्या आड़े आया?", "ar": "ما الذي وقف في الطريق؟"],
        "ns.acc.help.ph": ["en": "What would help? (optional)", "es": "¿Qué ayudaría? (opcional)", "fr": "Qu’est-ce qui aiderait ? (facultatif)", "de": "Was würde helfen? (optional)", "pt": "O que ajudaria? (opcional)", "it": "Cosa aiuterebbe? (facoltativo)", "ja": "何があれば助かりますか？（任意）", "zh": "什么会有帮助？（可选）", "hi": "क्या मदद करेगा? (वैकल्पिक)", "ar": "ما الذي قد يساعد؟ (اختياري)"],
        "ns.acc.send": ["en": "Send report", "es": "Enviar informe", "fr": "Envoyer le signalement", "de": "Bericht senden", "pt": "Enviar relato", "it": "Invia la segnalazione", "ja": "報告を送る", "zh": "发送报告", "hi": "रिपोर्ट भेजें", "ar": "أرسل البلاغ"],
        "ns.acc.sent": ["en": "Received — thank you.", "es": "Recibido. Gracias.", "fr": "Reçu — merci.", "de": "Angekommen — danke.", "pt": "Recebido — obrigado.", "it": "Ricevuto — grazie.", "ja": "受け取りました。ありがとうございます。", "zh": "已收到——谢谢。", "hi": "प्राप्त हुआ — धन्यवाद।", "ar": "وصل البلاغ — شكرًا لك."],
        "ns.acc.token.ph": ["en": "Reviewer token", "es": "Token de revisor", "fr": "Jeton de réviseur", "de": "Prüfer-Token", "pt": "Token de revisor", "it": "Token del revisore", "ja": "レビュアートークン", "zh": "审阅者令牌", "hi": "समीक्षक टोकन", "ar": "رمز المراجع"],
        "ns.acc.load": ["en": "Load reports", "es": "Cargar informes", "fr": "Charger les signalements", "de": "Berichte laden", "pt": "Carregar relatos", "it": "Carica le segnalazioni", "ja": "報告を読み込む", "zh": "载入报告", "hi": "रिपोर्टें लोड करें", "ar": "حمّل البلاغات"],
        "ns.acc.none": ["en": "No reports yet.", "es": "Aún no hay informes.", "fr": "Aucun signalement pour l’instant.", "de": "Noch keine Berichte.", "pt": "Ainda não há relatos.", "it": "Ancora nessuna segnalazione.", "ja": "まだ報告はありません。", "zh": "还没有报告。", "hi": "अभी कोई रिपोर्ट नहीं।", "ar": "لا بلاغات بعد."],
        "set.invite": ["en": "Invite key", "es": "Clave de invitación", "fr": "Clé d’invitation", "de": "Einladungsschlüssel", "pt": "Chave de convite", "it": "Chiave di invito", "ja": "招待キー", "zh": "邀请密钥", "hi": "आमंत्रण कुंजी", "ar": "مفتاح الدعوة"],
        "set.invite.lead": ["en": "This deployment requires an invite key to create an account — the person who runs it can give you one.", "es": "Esta instalación requiere una clave de invitación para crear una cuenta; quien la administra puede dártela.", "fr": "Cette installation exige une clé d’invitation pour créer un compte — la personne qui la gère peut vous en fournir une.", "de": "Diese Installation verlangt zum Erstellen eines Kontos einen Einladungsschlüssel — die betreibende Person kann ihn dir geben.", "pt": "Esta instalação exige uma chave de convite para criar uma conta — quem a administra pode fornecê-la.", "it": "Questa installazione richiede una chiave di invito per creare un account: chi la gestisce può fornirtela.", "ja": "この環境でアカウントを作成するには招待キーが必要です。運営者から受け取ってください。", "zh": "此部署需要邀请密钥才能创建账户——请向运营者索取。", "hi": "इस परिनियोजन में खाता बनाने के लिए आमंत्रण कुंजी आवश्यक है — इसे चलाने वाला व्यक्ति आपको दे सकता है।", "ar": "يتطلب هذا النشر مفتاح دعوة لإنشاء حساب — يمكن لمن يديره أن يعطيك إياه."],
        "set.key": ["en": "Your model API key", "es": "Tu clave de API del modelo", "fr": "Votre clé d'API du modèle", "de": "Ihr Modell-API-Schlüssel", "pt": "A sua chave de API do modelo", "it": "La tua chiave API del modello", "ja": "あなたのモデルAPIキー", "zh": "你的模型 API 密钥", "hi": "आपकी मॉडल API कुंजी", "ar": "مفتاح واجهة النموذج الخاص بك"],
        "set.key.pitch": ["en": "Paste your own key (Anthropic sk-ant-…, or OpenAI / xAI / Gemini for those providers) and your Guardian's replies run on your credential. It stays on this device and rides only your own requests — the server never stores it. Leave it empty to use whatever key the deployment lends.", "es": "Pega tu propia clave (Anthropic sk-ant-…, o de OpenAI / xAI / Gemini para esos proveedores) y las respuestas de tu Guardián correrán con tu credencial. Se queda en este dispositivo y viaja solo con tus propias peticiones — el servidor nunca la almacena. Déjala vacía para usar la clave que preste el despliegue.", "fr": "Collez votre propre clé (Anthropic sk-ant-…, ou OpenAI / xAI / Gemini pour ces fournisseurs) et les réponses de votre Gardien tournent sur votre identifiant. Elle reste sur cet appareil et n'accompagne que vos propres requêtes — le serveur ne la stocke jamais. Laissez-la vide pour utiliser la clé que prête le déploiement.", "de": "Fügen Sie Ihren eigenen Schlüssel ein (Anthropic sk-ant-…, oder OpenAI / xAI / Gemini für diese Anbieter), und die Antworten Ihres Guardians laufen auf Ihrem Zugang. Er bleibt auf diesem Gerät und reist nur mit Ihren eigenen Anfragen — der Server speichert ihn nie. Lassen Sie ihn leer, um den Schlüssel zu nutzen, den das Deployment leiht.", "pt": "Cole a sua própria chave (Anthropic sk-ant-…, ou OpenAI / xAI / Gemini para esses fornecedores) e as respostas do seu Guardião correm com a sua credencial. Fica neste dispositivo e viaja só com os seus próprios pedidos — o servidor nunca a guarda. Deixe-a vazia para usar a chave que o deployment empresta.", "it": "Incolla la tua chiave (Anthropic sk-ant-…, oppure OpenAI / xAI / Gemini per quei provider) e le risposte del tuo Guardian girano sulla tua credenziale. Resta su questo dispositivo e viaggia solo con le tue richieste — il server non la memorizza mai. Lasciala vuota per usare la chiave che presta il deployment.", "ja": "自分のキーを貼り付けてください（Anthropicは sk-ant-…、各プロバイダーはOpenAI / xAI / Gemini のもの）。するとガーディアンの返答はあなたの資格情報で動きます。キーはこの端末に留まり、あなた自身のリクエストにだけ同行します — サーバーが保存することはありません。空欄にすれば、この配備が貸すキーが使われます。", "zh": "粘贴你自己的密钥（Anthropic 用 sk-ant-…，对应提供方则用 OpenAI / xAI / Gemini 的密钥），你的守护者的回复便以你的凭证运行。它留在本设备上，只随你自己的请求同行 — 服务器绝不存储它。留空则使用本部署出借的密钥。", "hi": "अपनी कुंजी चिपकाएँ (Anthropic के लिए sk-ant-…, या उन प्रदाताओं के लिए OpenAI / xAI / Gemini) और आपके गार्जियन के जवाब आपकी क्रेडेंशियल पर चलेंगे। यह इसी डिवाइस पर रहती है और केवल आपके अपने अनुरोधों के साथ जाती है — सर्वर इसे कभी संग्रहित नहीं करता। खाली छोड़ें तो डिप्लॉयमेंट जो कुंजी उधार देता है वही चलेगी।", "ar": "الصق مفتاحك الخاص (Anthropic بصيغة sk-ant-…، أو OpenAI / xAI / Gemini لتلك المزودات) فتعمل ردود حارسك على اعتمادك. يبقى على هذا الجهاز ويرافق طلباتك أنت فقط — ولا يخزّنه الخادم أبدًا. اتركه فارغًا لاستخدام المفتاح الذي يعيره هذا النشر."],
        "set.key.label": ["en": "API key", "es": "Clave de API", "fr": "Clé d'API", "de": "API-Schlüssel", "pt": "Chave de API", "it": "Chiave API", "ja": "APIキー", "zh": "API 密钥", "hi": "API कुंजी", "ar": "مفتاح الواجهة"],
        "set.key.ph": ["en": "sk-…", "es": "sk-…", "fr": "sk-…", "de": "sk-…", "pt": "sk-…", "it": "sk-…", "ja": "sk-…", "zh": "sk-…", "hi": "sk-…", "ar": "sk-…"],
        "ov.language": ["en": "Language", "es": "Idioma", "fr": "Langue", "de": "Sprache", "pt": "Idioma", "it": "Lingua", "ja": "言語", "zh": "语言", "hi": "भाषा", "ar": "اللغة"],
        "ov.language.sub": ["en": "Everything drafted for you — guidance, coaching, first-aid steps, waiver terms — is delivered in this language.", "es": "Todo lo que se redacta para ti —indicaciones, acompañamiento, primeros auxilios, cláusulas del consentimiento— llega en este idioma.", "fr": "Tout ce qui est rédigé pour vous — conseils, accompagnement, gestes de premiers secours, termes de la renonciation — vous parvient dans cette langue.", "de": "Alles, was für dich verfasst wird — Hinweise, Coaching, Erste-Hilfe-Schritte, Verzichtsklauseln — kommt in dieser Sprache.", "pt": "Tudo o que é redigido para si — orientações, acompanhamento, passos de primeiros socorros, cláusulas do consentimento — chega neste idioma.", "it": "Tutto ciò che viene scritto per te — indicazioni, coaching, gesti di primo soccorso, clausole della liberatoria — arriva in questa lingua.", "ja": "あなたのために書かれるものはすべて——案内、コーチング、応急手当の手順、同意書の文言——この言語で届きます。", "zh": "为你撰写的一切 — 指导、辅导、急救步骤、授权条款 — 都以这种语言呈现。", "hi": "आपके लिए लिखी जाने वाली हर चीज़ — मार्गदर्शन, कोचिंग, प्राथमिक उपचार के चरण, अनुमति-पत्र की शर्तें — इसी भाषा में मिलती है।", "ar": "كل ما يُصاغ لك — الإرشاد والتدريب وخطوات الإسعاف وبنود التنازل — يصلك بهذه اللغة."],
        "ov.pretranslate": ["en": "Pre-translate everything", "es": "Traducir todo de antemano", "fr": "Tout pré-traduire", "de": "Alles vorab übersetzen", "pt": "Traduzir tudo de antemão", "it": "Pretradurre tutto", "ja": "すべてをあらかじめ翻訳", "zh": "预先翻译全部内容", "hi": "सब कुछ पहले से अनुवाद करें", "ar": "ترجم كل شيء مسبقًا"],
        "ov.pretranslate.sub": ["en": "Off keeps originals — translate selectively below.", "es": "Desactivado conserva los originales; traduce lo que quieras más abajo.", "fr": "Désactivé conserve les originaux — traduisez au cas par cas ci-dessous.", "de": "Aus behält die Originale — übersetze unten gezielt.", "pt": "Desligado mantém os originais — traduza pontualmente abaixo.", "it": "Disattivato mantiene gli originali — traduci in modo selettivo qui sotto.", "ja": "オフのままなら原文が残ります。下で必要なものだけ翻訳できます。", "zh": "关闭时保留原文 — 可在下方按需翻译。", "hi": "बंद रहने पर मूल पाठ बना रहता है — नीचे चुनकर अनुवाद कीजिए।", "ar": "الإيقاف يبقي النصوص الأصلية — وترجم ما تشاء أدناه."],
        "ov.translate": ["en": "Translate anything", "es": "Traducir cualquier cosa", "fr": "Traduire n'importe quoi", "de": "Beliebiges übersetzen", "pt": "Traduzir qualquer coisa", "it": "Traduci qualsiasi cosa", "ja": "何でも翻訳", "zh": "翻译任何内容", "hi": "कुछ भी अनुवाद करें", "ar": "ترجم أي شيء"],
        "ov.translate.sub": ["en": "Anything you run across — a note, a message, a label — into {lang}.", "es": "Lo que te encuentres —una nota, un mensaje, una etiqueta— a {lang}.", "fr": "Tout ce que vous croisez — une note, un message, une étiquette — vers {lang}.", "de": "Alles, was dir begegnet — eine Notiz, eine Nachricht, ein Etikett — nach {lang}.", "pt": "O que encontrar — uma nota, uma mensagem, um rótulo — para {lang}.", "it": "Qualsiasi cosa incontri — una nota, un messaggio, un'etichetta — in {lang}.", "ja": "目にしたもの——メモ、メッセージ、ラベル——を {lang} に。", "zh": "你遇到的任何内容 — 一张便条、一条消息、一个标签 — 译成 {lang}。", "hi": "जो भी सामने आए — कोई नोट, संदेश या लेबल — उसे {lang} में।", "ar": "أي شيء تصادفه — ملاحظة أو رسالة أو ملصق — إلى {lang}."],
        "ov.translate.yours": ["en": "your language", "es": "tu idioma", "fr": "votre langue", "de": "deine Sprache", "pt": "o seu idioma", "it": "la tua lingua", "ja": "あなたの言語", "zh": "你的语言", "hi": "आपकी भाषा", "ar": "لغتك"],
        "ov.translate.placeholder": ["en": "Paste or type text…", "es": "Pega o escribe un texto…", "fr": "Collez ou saisissez du texte…", "de": "Text einfügen oder tippen …", "pt": "Cole ou escreva um texto…", "it": "Incolla o scrivi del testo…", "ja": "テキストを貼り付けるか入力…", "zh": "粘贴或输入文字…", "hi": "पाठ चिपकाएँ या लिखें…", "ar": "الصق نصًا أو اكتبه…"],
        "ov.learned": ["en": "What JIM has learned about you", "es": "Lo que JIM ha aprendido sobre ti", "fr": "Ce que JIM a appris sur vous", "de": "Was JIM über dich gelernt hat", "pt": "O que o JIM aprendeu sobre si", "it": "Ciò che JIM ha imparato su di te", "ja": "JIM があなたについて学んだこと", "zh": "JIM 对你的了解", "hi": "JIM ने आपके बारे में क्या सीखा", "ar": "ما تعلَّمه JIM عنك"],
        "ov.confidence": ["en": "Confidence {pct}% — earned from {n} things already on your record.", "es": "Confianza {pct} %: se basa en {n} elementos que ya están en tu registro.", "fr": "Confiance {pct} % — établie à partir de {n} éléments déjà présents dans votre dossier.", "de": "Zuversicht {pct} % — aus {n} Dingen, die schon in deiner Akte stehen.", "pt": "Confiança {pct}% — assente em {n} elementos já no seu registo.", "it": "Fiducia {pct}% — ricavata da {n} elementi già presenti nel tuo archivio.", "ja": "確からしさ {pct}% ——すでに記録にある {n} 件から導いています。", "zh": "把握度 {pct}% — 来自你记录中已有的 {n} 项。", "hi": "विश्वास {pct}% — आपके रिकॉर्ड में पहले से मौजूद {n} चीज़ों से बना।", "ar": "الثقة {pct}% — مستمدة من {n} عنصرًا في سجلّك بالفعل."],
        "ov.helped": ["en": "helped {n} of {total}", "es": "ayudó {n} de {total}", "fr": "a aidé {n} fois sur {total}", "de": "half {n} von {total}", "pt": "ajudou {n} de {total}", "it": "ha aiutato {n} su {total}", "ja": "{total} 回中 {n} 回役に立ちました", "zh": "{total} 次中有 {n} 次有帮助", "hi": "{total} में से {n} बार मदद मिली", "ar": "أفاد {n} من {total}"],
        "ov.tone": ["en": "Tone you asked for: {tone}", "es": "Tono que pediste: {tone}", "fr": "Ton que vous avez demandé : {tone}", "de": "Der Ton, um den du gebeten hast: {tone}", "pt": "Tom que pediu: {tone}", "it": "Il tono che hai chiesto: {tone}", "ja": "あなたが望んだ話し方：{tone}", "zh": "你要求的语气：{tone}", "hi": "आपने जो लहजा माँगा: {tone}", "ar": "النبرة التي طلبتها: {tone}"],
        "ov.work": ["en": "Work you named: {job}", "es": "El trabajo que mencionaste: {job}", "fr": "Le métier que vous avez nommé : {job}", "de": "Die Arbeit, die du genannt hast: {job}", "pt": "O trabalho que indicou: {job}", "it": "Il lavoro che hai indicato: {job}", "ja": "あなたが挙げた仕事：{job}", "zh": "你说过的工作：{job}", "hi": "आपने जो काम बताया: {job}", "ar": "العمل الذي ذكرته: {job}"],
        "ov.sealed": ["en": "Sealed in your own vault.", "es": "Sellado en tu propia bóveda.", "fr": "Scellé dans votre propre coffre.", "de": "In deinem eigenen Tresor versiegelt.", "pt": "Selado no seu próprio cofre.", "it": "Sigillato nel tuo caveau.", "ja": "あなた自身の保管庫に封印されています。", "zh": "封存在你自己的保险库中。", "hi": "आपकी अपनी तिजोरी में सील किया गया।", "ar": "مختوم في خزنتك أنت."],
        "ov.name": ["en": "Your name here", "es": "Tu nombre aquí", "fr": "Votre nom ici", "de": "Dein Name hier", "pt": "O seu nome aqui", "it": "Il tuo nome qui", "ja": "ここでのあなたの名前", "zh": "你在这里的名字", "hi": "यहाँ आपका नाम", "ar": "اسمك هنا"],
        "ov.name.pseudonym": ["en": "You are known here as {name}.", "es": "Aquí se te conoce como {name}.", "fr": "Ici, vous êtes connu sous le nom de {name}.", "de": "Hier bist du als {name} bekannt.", "pt": "Aqui é conhecido como {name}.", "it": "Qui sei conosciuto come {name}.", "ja": "ここでのあなたは {name} として知られています。", "zh": "在这里，你以 {name} 为人所知。", "hi": "यहाँ आप {name} के रूप में जाने जाते हैं।", "ar": "تُعرَف هنا باسم {name}."],
        "ov.name.own": ["en": "You are enrolled under your own name.", "es": "Estás inscrito con tu propio nombre.", "fr": "Vous êtes inscrit sous votre propre nom.", "de": "Du bist unter deinem eigenen Namen angemeldet.", "pt": "Está inscrito com o seu próprio nome.", "it": "Sei registrato con il tuo vero nome.", "ja": "あなたは本名で登録されています。", "zh": "你是以真名注册的。", "hi": "आप अपने असली नाम से पंजीकृत हैं।", "ar": "أنت مسجَّل باسمك الحقيقي."],
        "ov.name.pseudonym.fallback": ["en": "a pseudonym", "es": "un seudónimo", "fr": "un pseudonyme", "de": "ein Pseudonym", "pt": "um pseudónimo", "it": "uno pseudonimo", "ja": "仮の名前", "zh": "一个化名", "hi": "एक छद्म नाम", "ar": "اسم مستعار"],
        "ov.legal": ["en": "A legal name is on record for responders.", "es": "Hay un nombre legal registrado para quienes acudan a ayudarte.", "fr": "Un nom légal est enregistré pour les secours.", "de": "Für die Rettungskräfte ist ein amtlicher Name hinterlegt.", "pt": "Existe um nome legal registado para quem venha socorrê-lo.", "it": "Un nome legale è agli atti per chi interviene.", "ja": "駆けつける人のために、戸籍上の名前が記録されています。", "zh": "为前来救助的人保留了一个法定姓名记录。", "hi": "मदद के लिए आने वालों के लिए एक क़ानूनी नाम दर्ज है।", "ar": "ثمة اسم قانوني مُدوَّن لمن يهرعون لنجدتك."],
        "ov.loading": ["en": "Loading…", "es": "Cargando…", "fr": "Chargement…", "de": "Wird geladen …", "pt": "A carregar…", "it": "Caricamento…", "ja": "読み込み中…", "zh": "正在加载…", "hi": "लोड हो रहा है…", "ar": "جارٍ التحميل…"],
        "alarm.lead.short": ["en": "Alarms", "es": "Alarmas", "fr": "Alertes", "de": "Alarme", "pt": "Alarmes", "it": "Allarmi", "ja": "アラーム", "zh": "警报", "hi": "अलार्म", "ar": "الإنذارات"],
