        "alarm.tripped": ["en": "The crash watch tripped: {name} was contacted. Any normal reading stands it down.", "es": "La vigilancia de caídas se activó: se contactó a {name}. Cualquier lectura normal la desactiva.", "fr": "La veille d'accident s'est déclenchée : {name} a été contacté. Toute mesure normale la désarme.", "de": "Die Sturzwache hat ausgelöst: {name} wurde benachrichtigt. Jeder normale Messwert setzt sie zurück.", "pt": "A vigilância de queda disparou: {name} foi contactado. Qualquer leitura normal desativa-a.", "it": "La sorveglianza incidenti è scattata: {name} è stato contattato. Qualsiasi misurazione normale la disattiva.", "ja": "クラッシュウォッチが作動しました：{name} に連絡しました。通常の測定値が届けば解除されます。", "zh": "跌倒守护已触发：已联系 {name}。任何正常读数都会将其解除。", "hi": "क्रैश वॉच सक्रिय हो गई: {name} से संपर्क किया गया। कोई भी सामान्य रीडिंग इसे बंद कर देती है।", "ar": "تم تفعيل مراقبة الحوادث: جرى الاتصال بـ {name}. وأي قراءة طبيعية تُلغيها."],
        "alarm.armed": ["en": "Armed — {name} will be contacted after {n} unanswered attempts.", "es": "Activada — se contactará a {name} tras {n} intentos sin respuesta.", "fr": "Armée — {name} sera contacté après {n} tentatives sans réponse.", "de": "Scharf — {name} wird nach {n} unbeantworteten Versuchen benachrichtigt.", "pt": "Armada — {name} será contactado após {n} tentativas sem resposta.", "it": "Attiva — {name} verrà contattato dopo {n} tentativi senza risposta.", "ja": "作動中 — 応答のない確認が {n} 回続くと {name} に連絡します。", "zh": "已启用 — 在 {n} 次无人应答后将联系 {name}。", "hi": "सक्रिय — {n} बार उत्तर न मिलने पर {name} से संपर्क किया जाएगा।", "ar": "مُفعَّلة — سيجري الاتصال بـ {name} بعد {n} محاولات دون رد."],
        "alarm.ems": ["en": "May request emergency services (relayed as a request — this app cannot itself place a call)", "es": "Puede solicitar servicios de emergencia (se transmite como una solicitud — esta app no puede llamar por sí misma)", "fr": "Peut demander les services d'urgence (transmis comme une demande — cette application ne peut pas passer d'appel elle-même)", "de": "Darf Rettungsdienste anfordern (als Anfrage weitergeleitet — diese App kann selbst nicht anrufen)", "pt": "Pode pedir serviços de emergência (transmitido como um pedido — esta aplicação não pode fazer chamadas)", "it": "Può richiedere i servizi di emergenza (inoltrato come richiesta — questa app non può effettuare chiamate)", "ja": "緊急サービスの要請を許可する（要請として転送されます。このアプリ自体は通報できません）", "zh": "可以请求紧急服务（以请求的形式转达 — 本应用本身无法拨打电话）", "hi": "आपातकालीन सेवाओं का अनुरोध कर सकता है (अनुरोध के रूप में भेजा जाता है — यह ऐप स्वयं कॉल नहीं कर सकता)", "ar": "قد يطلب خدمات الطوارئ (يُنقل بوصفه طلبًا — لا يمكن لهذا التطبيق إجراء مكالمة بنفسه)"],
        "offline.title": ["en": "What this deployment can reach", "es": "Qué puede alcanzar esta instalación", "fr": "Ce que ce déploiement peut atteindre", "de": "Was diese Installation erreichen kann", "pt": "O que esta instalação pode alcançar", "it": "Cosa può raggiungere questa installazione", "ja": "この環境が接続できる範囲", "zh": "此部署可以连接到什么", "hi": "यह परिनियोजन किस तक पहुँच सकता है", "ar": "ما يمكن أن يصل إليه هذا النشر"],
        "offline.on": ["en": "Offline — nothing leaves this machine", "es": "Sin conexión — nada sale de esta máquina", "fr": "Hors ligne — rien ne quitte cette machine", "de": "Offline — nichts verlässt diesen Rechner", "pt": "Offline — nada sai desta máquina", "it": "Offline — nulla esce da questa macchina", "ja": "オフライン — このマシンから何も出ません", "zh": "离线 — 任何内容都不会离开这台机器", "hi": "ऑफ़लाइन — इस मशीन से कुछ भी बाहर नहीं जाता", "ar": "دون اتصال — لا شيء يغادر هذا الجهاز"],
        "offline.off": ["en": "Online — this deployment can reach other machines", "es": "En línea — esta instalación puede alcanzar otras máquinas", "fr": "En ligne — ce déploiement peut atteindre d’autres machines", "de": "Online — diese Installation kann andere Rechner erreichen", "pt": "Online — esta instalação pode alcançar outras máquinas", "it": "Online — questa installazione può raggiungere altre macchine", "ja": "オンライン — この環境は他のマシンに接続できます", "zh": "在线 — 此部署可以连接其他机器", "hi": "ऑनलाइन — यह परिनियोजन अन्य मशीनों तक पहुँच सकता है", "ar": "متصل — يمكن لهذا النشر الوصول إلى أجهزة أخرى"],
        "tab.overview": ["en": "Overview", "es": "Resumen", "fr": "Aperçu",
                         "de": "Übersicht", "pt": "Visão geral", "it": "Panoramica",
                         "ja": "概要", "zh": "概览", "hi": "अवलोकन", "ar": "نظرة عامة"],
        "self.profile_id": ["en": "prf_…", "es": "prf_…", "fr": "prf_…", "de": "prf_…", "pt": "prf_…", "it": "prf_…", "ja": "prf_…", "zh": "prf_…", "hi": "prf_…", "ar": "prf_…"],
        "self.title": ["en": "Your own profile", "es": "Tu propio perfil", "fr": "Votre propre profil", "de": "Ihr eigenes Profil", "pt": "O seu próprio perfil", "it": "Il tuo profilo", "ja": "あなた自身のプロフィール", "zh": "你自己的档案", "hi": "आपकी अपनी प्रोफ़ाइल", "ar": "ملفك الشخصي"],
        "self.lead": ["en": "The QRME profile that speaks as you. The Guardian tells it nothing until you say which parts it may pass on, and you can see exactly what would go before any of it does.", "es": "El perfil de QRME que habla como tú. El Guardián no le cuenta nada hasta que digas qué partes puede transmitir, y puedes ver exactamente qué se enviaría antes de que se envíe.", "fr": "Le profil QRME qui parle en votre nom. Le Gardien ne lui dit rien tant que vous n’avez pas indiqué ce qu’il peut transmettre, et vous voyez exactement ce qui partirait avant que quoi que ce soit parte.", "de": "Das QRME-Profil, das als Sie spricht. Der Guardian sagt ihm nichts, bis Sie festlegen, was er weitergeben darf, und Sie sehen genau, was ginge, bevor irgendetwas geht.", "pt": "O perfil QRME que fala como você. O Guardião não lhe conta nada até dizer que partes pode transmitir, e vê exatamente o que iria antes de qualquer coisa ir.", "it": "Il profilo QRME che parla come te. Il Guardian non gli dice nulla finché non indichi cosa può trasmettere, e vedi esattamente cosa partirebbe prima che parta.", "ja": "あなたとして話す QRME のプロフィールです。どの部分を伝えてよいか決めるまで、ガーディアンは何も伝えません。送られる内容は送信前にそのまま確認できます。", "zh": "以你的身份说话的 QRME 档案。在你指明可以转达哪些部分之前，守护者不会告诉它任何事，而且发送前你能看到确切会送出什么。", "hi": "वह QRME प्रोफ़ाइल जो आपके रूप में बोलती है। जब तक आप यह न बताएँ कि कौन-से हिस्से भेजे जा सकते हैं, गार्जियन उसे कुछ नहीं बताता, और भेजे जाने से पहले आप ठीक-ठीक देख सकते हैं कि क्या जाएगा।", "ar": "ملف QRME الذي يتحدث بصفتك. لا يخبره الحارس بشيء حتى تحدد ما يمكن نقله، ويمكنك أن ترى بالضبط ما سيُرسل قبل أن يُرسل أي شيء."],
        "self.link": ["en": "Link it", "es": "Vincúlalo", "fr": "Le relier", "de": "Verknüpfen", "pt": "Ligar", "it": "Collegalo", "ja": "リンクする", "zh": "关联它", "hi": "इसे जोड़ें", "ar": "اربطه"],
        "self.paste": ["en": "Paste the profile's id and your owner token from QRME. It has to be a profile QRME calls your own — a made-up one will be refused.", "es": "Pega el id del perfil y tu token de propietario de QRME. Tiene que ser un perfil que QRME considere tuyo; uno inventado será rechazado.", "fr": "Collez l’identifiant du profil et votre jeton de propriétaire QRME. Ce doit être un profil que QRME reconnaît comme le vôtre ; un profil inventé sera refusé.", "de": "Fügen Sie die Profil-ID und Ihr Eigentümer-Token aus QRME ein. Es muss ein Profil sein, das QRME als Ihr eigenes führt — ein erfundenes wird abgelehnt.", "pt": "Cole o id do perfil e o seu token de proprietário do QRME. Tem de ser um perfil que o QRME considere seu — um inventado será recusado.", "it": "Incolla l’id del profilo e il tuo token di proprietario da QRME. Deve essere un profilo che QRME riconosce come tuo — uno inventato verrà rifiutato.", "ja": "QRME のプロフィール ID と所有者トークンを貼り付けてください。QRME があなた自身のものと認めるプロフィールに限られ、架空のものは拒否されます。", "zh": "粘贴档案 id 和你在 QRME 的所有者令牌。必须是 QRME 认定属于你自己的档案 — 编造的会被拒绝。", "hi": "QRME से प्रोफ़ाइल का id और अपना स्वामी टोकन चिपकाएँ। यह ऐसी प्रोफ़ाइल होनी चाहिए जिसे QRME आपकी अपनी मानता हो — बनावटी को अस्वीकार कर दिया जाएगा।", "ar": "الصق معرِّف الملف ورمز المالك الخاص بك من QRME. يجب أن يكون ملفًا يعتبره QRME ملكك — وسيُرفض أي ملف مُختلق."],
        "self.owner_token": ["en": "owner token", "es": "token de propietario", "fr": "jeton de propriétaire", "de": "Eigentümer-Token", "pt": "token de proprietário", "it": "token di proprietario", "ja": "所有者トークン", "zh": "所有者令牌", "hi": "स्वामी टोकन", "ar": "رمز المالك"],
        "self.link_button": ["en": "Link this profile", "es": "Vincular este perfil", "fr": "Relier ce profil", "de": "Dieses Profil verknüpfen", "pt": "Ligar este perfil", "it": "Collega questo profilo", "ja": "このプロフィールをリンク", "zh": "关联此档案", "hi": "इस प्रोफ़ाइल को जोड़ें", "ar": "اربط هذا الملف"],
        "self.may_know": ["en": "What it may know", "es": "Qué puede saber", "fr": "Ce qu’il peut savoir", "de": "Was es wissen darf", "pt": "O que pode saber", "it": "Cosa può sapere", "ja": "伝えてよいこと", "zh": "它可以知道什么", "hi": "यह क्या जान सकता है", "ar": "ما يمكن أن يعرفه"],
        "self.until_tick": ["en": "Nothing is passed on until you tick it.", "es": "No se transmite nada hasta que lo marques.", "fr": "Rien n’est transmis tant que vous ne l’avez pas coché.", "de": "Nichts wird weitergegeben, bis Sie es ankreuzen.", "pt": "Nada é transmitido até o marcar.", "it": "Non viene trasmesso nulla finché non lo spunti.", "ja": "チェックするまで何も伝えられません。", "zh": "在你勾选之前，不会转达任何内容。", "hi": "जब तक आप चुनें नहीं, कुछ भी नहीं भेजा जाता।", "ar": "لا يُنقل شيء حتى تحدده."],
        "self.exactly": ["en": "Exactly what would be sent", "es": "Exactamente lo que se enviaría", "fr": "Exactement ce qui serait envoyé", "de": "Genau das, was gesendet würde", "pt": "Exatamente o que seria enviado", "it": "Esattamente ciò che verrebbe inviato", "ja": "送られる内容そのもの", "zh": "确切会发送的内容", "hi": "ठीक वही जो भेजा जाएगा", "ar": "ما سيُرسل بالضبط"],
        "self.nothing_ticked": ["en": "Nothing, because nothing is ticked.", "es": "Nada, porque no hay nada marcado.", "fr": "Rien, parce que rien n’est coché.", "de": "Nichts, weil nichts angekreuzt ist.", "pt": "Nada, porque nada está marcado.", "it": "Niente, perché non è spuntato nulla.", "ja": "何もチェックされていないため、何もありません。", "zh": "没有内容，因为没有勾选任何项。", "hi": "कुछ नहीं, क्योंकि कुछ चुना नहीं गया है।", "ar": "لا شيء، لأنه لم يتم تحديد أي شيء."],
        "self.message_itself": ["en": "This is the message itself, not a description of it. Medication is the one part made of your own words, so it shows the names as you typed them.", "es": "Este es el mensaje en sí, no una descripción. La medicación es la única parte hecha con tus propias palabras, así que muestra los nombres tal como los escribiste.", "fr": "Ceci est le message lui-même, pas sa description. Les médicaments sont la seule partie faite de vos propres mots : les noms s’affichent tels que vous les avez saisis.", "de": "Dies ist die Nachricht selbst, keine Beschreibung. Die Medikation ist der einzige Teil aus Ihren eigenen Worten, daher erscheinen die Namen so, wie Sie sie eingegeben haben.", "pt": "Esta é a mensagem em si, não uma descrição. A medicação é a única parte feita das suas próprias palavras, por isso mostra os nomes tal como os escreveu.", "it": "Questo è il messaggio stesso, non una sua descrizione. I farmaci sono l’unica parte fatta di parole tue, quindi i nomi appaiono come li hai scritti.", "ja": "これは説明ではなく、メッセージそのものです。薬だけはご自身の言葉でできているため、入力したとおりの名称が表示されます。", "zh": "这就是消息本身，而不是对它的描述。用药是唯一由你自己的措辞构成的部分，因此名称按你输入的原样显示。", "hi": "यह संदेश स्वयं है, उसका विवरण नहीं। दवा ही एकमात्र हिस्सा है जो आपके अपने शब्दों से बना है, इसलिए नाम वैसे ही दिखते हैं जैसे आपने लिखे।", "ar": "هذه هي الرسالة نفسها، لا وصفٌ لها. الدواء هو الجزء الوحيد المكوَّن من كلماتك، لذا تظهر الأسماء كما كتبتها."],
        "self.send": ["en": "Send this to my profile", "es": "Enviar esto a mi perfil", "fr": "Envoyer ceci à mon profil", "de": "Dies an mein Profil senden", "pt": "Enviar isto ao meu perfil", "it": "Invia questo al mio profilo", "ja": "これを自分のプロフィールに送る", "zh": "把这个发送到我的档案", "hi": "इसे मेरी प्रोफ़ाइल को भेजें", "ar": "أرسل هذا إلى ملفي"],
        "self.stop": ["en": "Stop", "es": "Detener", "fr": "Arrêter", "de": "Beenden", "pt": "Parar", "it": "Ferma", "ja": "やめる", "zh": "停止", "hi": "रोकें", "ar": "إيقاف"],
        "self.unlink_note": ["en": "Unlinking removes the token and everything you ticked. What the profile was already told stays in its own source list, in QRME, where you can delete it.", "es": "Desvincular elimina el token y todo lo que marcaste. Lo que ya se le dijo al perfil permanece en su propia lista de fuentes, en QRME, donde puedes borrarlo.", "fr": "Le fait de délier supprime le jeton et tout ce que vous aviez coché. Ce qui a déjà été dit au profil reste dans sa liste de sources, dans QRME, où vous pouvez le supprimer.", "de": "Das Trennen entfernt das Token und alles, was Sie angekreuzt hatten. Was dem Profil bereits mitgeteilt wurde, bleibt in dessen Quellenliste in QRME, wo Sie es löschen können.", "pt": "Desligar remove o token e tudo o que marcou. O que já foi dito ao perfil fica na sua própria lista de fontes, no QRME, onde o pode apagar.", "it": "Scollegare rimuove il token e tutto ciò che avevi spuntato. Quanto già detto al profilo resta nel suo elenco di fonti, in QRME, dove puoi eliminarlo.", "ja": "リンクを解除するとトークンとチェックした内容がすべて削除されます。すでにプロフィールに伝えた内容は QRME のソース一覧に残り、そこで削除できます。", "zh": "取消关联会移除令牌和你勾选的全部内容。已经告诉档案的内容仍留在 QRME 的来源列表中，你可以在那里删除。", "hi": "अनलिंक करने से टोकन और आपके चुने हुए सब कुछ हट जाता है। प्रोफ़ाइल को पहले जो बताया जा चुका है वह QRME की उसकी स्रोत सूची में रहता है, जहाँ आप उसे मिटा सकते हैं।", "ar": "يؤدي إلغاء الربط إلى إزالة الرمز وكل ما حددته. ويبقى ما قيل للملف سابقًا في قائمة مصادره داخل QRME، حيث يمكنك حذفه."],
        "self.unlink": ["en": "Unlink", "es": "Desvincular", "fr": "Dissocier", "de": "Trennen", "pt": "Desvincular", "it": "Scollega", "ja": "リンク解除", "zh": "取消关联", "hi": "अनलिंक करें", "ar": "إلغاء الربط"],
        "self.linked_note": ["en": "Linked. Nothing is shared yet.", "es": "Vinculado. Todavía no se comparte nada.", "fr": "Relié. Rien n’est encore partagé.", "de": "Verknüpft. Es wird noch nichts geteilt.", "pt": "Ligado. Ainda não é partilhado nada.", "it": "Collegato. Non è ancora condiviso nulla.", "ja": "リンクしました。まだ何も共有されていません。", "zh": "已关联。尚未共享任何内容。", "hi": "जुड़ गया। अभी कुछ भी साझा नहीं किया गया।", "ar": "تم الربط. لم تتم مشاركة أي شيء بعد."],
        "self.saved": ["en": "Saved.", "es": "Guardado.", "fr": "Enregistré.", "de": "Gespeichert.", "pt": "Guardado.", "it": "Salvato.", "ja": "保存しました。", "zh": "已保存。", "hi": "सहेजा गया।", "ar": "تم الحفظ."],
        "self.sent": ["en": "Sent.", "es": "Enviado.", "fr": "Envoyé.", "de": "Gesendet.", "pt": "Enviado.", "it": "Inviato.", "ja": "送信しました。", "zh": "已发送。", "hi": "भेज दिया गया।", "ar": "تم الإرسال."],
        "self.unlinked": ["en": "Unlinked.", "es": "Desvinculado.", "fr": "Délié.", "de": "Getrennt.", "pt": "Desligado.", "it": "Scollegato.", "ja": "リンクを解除しました。", "zh": "已取消关联。", "hi": "अनलिंक कर दिया गया।", "ar": "تم إلغاء الربط."],
